INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_1', 'How’s everything?', 'Nasıl gidiyor?', 'How’s everything at work?', 'A2', 20, 1, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_10', 'I owe you one.', 'Sana bir iyilik borcum var.', 'Thanks! I owe you one.', 'A2', 20, 10, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_11', 'It’s my pleasure.', 'Rica ederim.', 'It’s my pleasure to help.', 'A2', 20, 11, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_12', 'Do you have a minute?', 'Bir dakikan var mı?', 'Do you have a minute to talk?', 'A2', 20, 12, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_13', 'Sorry, I didn’t catch that.', 'Üzgünüm, anlayamadım.', 'Sorry, I didn’t catch that. Can you repeat?', 'A2', 20, 13, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_14', 'Could you say that again?', 'Tekrar eder misin?', 'Could you say that again, please?', 'A2', 20, 14, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_15', 'I think so.', 'Sanırım öyle.', 'Is the shop open now? — I think so.', 'A2', 20, 15, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_16', 'Let me check.', 'Kontrol edeyim.', 'Let me check the schedule.', 'A2', 20, 16, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_17', 'Guess what?', 'Bil bakalım ne oldu?', 'Guess what? I got the job!', 'A2', 20, 17, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_18', 'Take care.', 'Kendine iyi bak.', 'Bye! Take care.', 'A2', 20, 18, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_19', 'Same here.', 'Ben de aynı şekilde.', 'I love this place. — Same here.', 'A2', 20, 19, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_2', 'Long time no see!', 'Uzun zamandır görüşemedik!', 'Long time no see, how are you?', 'A2', 20, 2, '2026-06-11 13:02:44.778833+00');
