INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B1_24_76', 'as a final thought', 'son düşünce olarak', 'As a final thought, practice helps.', 'B1', 24, 76, '2026-06-11 13:02:44.822896+00');
