INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B1_24_9', 'this topic relates to', 'bu konu … ile ilgilidir', 'This topic relates to daily life.', 'B1', 24, 9, '2026-06-11 13:02:44.822896+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B1_25_1', 'Actually,', 'aslında', 'Actually, I wanted to say something.', 'B1', 25, 1, '2026-06-11 13:02:44.822896+00');
