INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B1_25_16', 'More or less', 'aşağı yukarı', 'It’s more or less finished.', 'B1', 25, 16, '2026-06-11 13:02:44.822896+00');
