INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B1_25_19', 'So,', 'peki', 'So, what do you think?', 'B1', 25, 19, '2026-06-11 13:02:44.822896+00');
