INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_56', 'This condition allows for', 'Bu koşul ...''a olanak sağlar', 'This condition allows for flexibility.', 'B2', 22, 56, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_57', 'This increases the likelihood that', 'Bu, ... olasılığını artırır', 'This increases the likelihood that goals are met.', 'B2', 22, 57, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_58', 'This depends on whether', 'Bu, ... olup olmamasına bağlıdır', 'This depends on whether support is provided.', 'B2', 22, 58, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_59', 'This creates an opportunity to', 'Bu, ... için bir fırsat yaratır', 'This creates an opportunity to innovate.', 'B2', 22, 59, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_6', 'This approach tends to', 'Bu yaklaşım genellikle ... eğilimindedir', 'This approach tends to overlook social factors.', 'B2', 22, 6, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_60', 'This remains possible only if', 'Bu, ancak ... ise mümkün olur', 'This remains possible only if resources are available.', 'B2', 22, 60, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_61', 'Taking all factors into account', 'Tüm faktörleri göz önünde bulundurarak', 'Taking all factors into account, change is necessary.', 'B2', 22, 61, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_62', 'This highlights the fact that', 'Bu, şu gerçeği vurgular:', 'This highlights the fact that inequality persists.', 'B2', 22, 62, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_63', 'It can therefore be concluded that', 'Dolayısıyla şu sonuca varılabilir ki', 'It can therefore be concluded that reform is urgent.', 'B2', 22, 63, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_64', 'This ultimately leads to', 'Bu nihayetinde ...''e yol açar', 'This ultimately leads to systemic change.', 'B2', 22, 64, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_65', 'The findings indicate that', 'Bulgular, ... olduğunu gösteriyor', 'The findings indicate that progress is uneven.', 'B2', 22, 65, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_66', 'This reinforces the idea that', 'Bu, ... fikrini güçlendirir', 'This reinforces the idea that planning matters.', 'B2', 22, 66, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_67', 'At the same time', 'Aynı zamanda', 'At the same time, risks must be managed.', 'B2', 22, 67, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_68', 'This calls into question whether', '... olup olmadığını sorgulatır', 'This calls into question whether the strategy works.', 'B2', 22, 68, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_69', 'In light of these considerations', 'Bu değerlendirmeler ışığında', 'In light of these considerations, action is required.', 'B2', 22, 69, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_7', 'It raises the question of whether', '... olup olmadığı sorusunu gündeme getirir', 'It raises the question of whether progress is sustainable.', 'B2', 22, 7, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_70', 'This demonstrates how', 'Bu, ... nasıl olduğunu gösterir', 'This demonstrates how systems adapt.', 'B2', 22, 70, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_71', 'The evidence suggests that', 'Kanıtlar, ... olduğunu düşündürüyor', 'The evidence suggests that outcomes vary.', 'B2', 22, 71, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_72', 'This marks a significant shift in', 'Bu, ... alanında önemli bir değişimi işaret eder', 'This marks a significant shift in policy.', 'B2', 22, 72, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_73', 'Overall, it appears that', 'Genel olarak, ... gibi görünüyor', 'Overall, it appears that progress is slow.', 'B2', 22, 73, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_74', 'This serves as an example of', 'Bu, ... için bir örnek teşkil eder', 'This serves as an example of effective planning.', 'B2', 22, 74, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_75', 'This underscores the importance of', 'Bu, ...''in önemini vurgular', 'This underscores the importance of transparency.', 'B2', 22, 75, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_76', 'As demonstrated by recent data', 'Son verilerin gösterdiği gibi', 'As demonstrated by recent data, trends are changing.', 'B2', 22, 76, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_77', 'This provides insight into', 'Bu, ... hakkında içgörü sağlar', 'This provides insight into decision-making.', 'B2', 22, 77, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_78', 'The results point to the need for', 'Sonuçlar, ... ihtiyacına işaret ediyor', 'The results point to the need for reform.', 'B2', 22, 78, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_79', 'This helps to clarify why', 'Bu, ... neden olduğunu netleştirmeye yardımcı olur', 'This helps to clarify why delays occurred.', 'B2', 22, 79, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_8', 'A key factor to consider is', 'Dikkate alınması gereken kilit bir faktör', 'A key factor to consider is the long-term impact.', 'B2', 22, 8, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_80', 'In summary, it can be stated that', 'Özetle, şu söylenebilir ki', 'In summary, it can be stated that cooperation is essential.', 'B2', 22, 80, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_9', 'It is worth noting that', 'Şunu belirtmek gerekir ki', 'It is worth noting that results vary.', 'B2', 22, 9, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_1', 'academic writing', 'akademik yazım', 'Academic writing avoids slang and informal words.', 'B2', 23, 1, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_10', 'objective language', 'nesnel dil', 'Academic essays require objective language.', 'B2', 23, 10, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_11', 'subheading', 'alt başlık', 'Each subheading tells the reader what the next part is about.', 'B2', 23, 11, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_12', 'style guide', 'yazım kılavuzu', 'Check the style guide before you format your references.', 'B2', 23, 12, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_13', 'wordiness', 'gereksiz sözcük kalabalığı', 'Cut wordiness by removing phrases like ''due to the fact that''.', 'B2', 23, 13, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_14', 'sentence fragment', 'eksik cümle', '''Because it was late.'' is a sentence fragment.', 'B2', 23, 14, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_15', 'transition word', 'geçiş sözcüğü', 'Add a transition word such as ''however'' between the two ideas.', 'B2', 23, 15, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_16', 'concise', 'kısa ve öz', 'Try to be concise and avoid long, complex sentences.', 'B2', 23, 16, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_17', 'essay prompt', 'kompozisyon sorusu', 'Read the essay prompt carefully before you start writing.', 'B2', 23, 17, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_18', 'proofread', 'metni hatalara karşı okuyup düzeltmek', 'Always proofread your essay before you hand it in.', 'B2', 23, 18, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_19', 'active voice', 'etken çatı', 'Use the active voice to make your sentences clearer.', 'B2', 23, 19, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_2', 'abstract', 'bilimsel makale özeti', 'Read the abstract first to decide if the article is useful.', 'B2', 23, 2, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_20', 'semicolon', 'noktalı virgül', 'Use a semicolon to join two closely related sentences.', 'B2', 23, 20, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_21', 'supporting evidence', 'destekleyici kanıt', 'Every claim in your essay needs supporting evidence.', 'B2', 23, 21, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_22', 'argumentative essay', 'tartışmacı deneme', 'In an argumentative essay, you take a clear position on an issue.', 'B2', 23, 22, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_23', 'make a case for', 'bir şeyin lehine gerekçeler sunmak', 'The author makes a strong case for free public transportation.', 'B2', 23, 23, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_24', 'concede', 'karşı görüşün haklı yanını kabul etmek', 'The writer concedes that the plan is expensive but still supports it.', 'B2', 23, 24, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_25', 'well-supported', 'sağlam kanıtlarla desteklenmiş', 'Her argument is clear and well-supported.', 'B2', 23, 25, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_26', 'one-sided', 'tek taraflı', 'The article is one-sided because it ignores the other view.', 'B2', 23, 26, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_27', 'peer feedback', 'akran geri bildirimi', 'Peer feedback helped me improve my essay.', 'B2', 23, 27, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_28', 'critical analysis', 'eleştirel çözümleme', 'The assignment asks for a critical analysis of the poem.', 'B2', 23, 28, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_29', 'sentence variety', 'cümle çeşitliliği', 'Mix short and long sentences to add sentence variety.', 'B2', 23, 29, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_3', 'clarity', 'anlaşılırlık', 'Short sentences improve the clarity of your writing.', 'B2', 23, 3, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_30', 'flawed', 'kusurlu', 'The study is flawed because only ten people took part.', 'B2', 23, 30, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_31', 'formal tone', 'resmî üslup', 'Keep a formal tone in academic essays.', 'B2', 23, 31, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_32', 'in-depth', 'derinlemesine', 'The report provides an in-depth look at the problem.', 'B2', 23, 32, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_33', 'unsupported claim', 'kanıtsız iddia', 'The essay was full of unsupported claims.', 'B2', 23, 33, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_34', 'run-on sentence', 'noktalaması eksik bitişik cümle', 'Fix the run-on sentence by adding a period.', 'B2', 23, 34, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_35', 'word limit', 'sözcük sınırı', 'The essay has a word limit of 1,500 words.', 'B2', 23, 35, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_36', 'stance', 'tutum', 'The author takes a clear stance against the death penalty.', 'B2', 23, 36, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_37', 'subject-verb agreement', 'özne-yüklem uyumu', '''The results shows'' is an error in subject-verb agreement.', 'B2', 23, 37, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_38', 'valid point', 'haklı bir nokta', 'You make a valid point about the costs.', 'B2', 23, 38, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_39', 'nuanced', 'incelikli', 'She gives a nuanced view of a complex issue.', 'B2', 23, 39, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_4', 'line of argument', 'savunulan düşünce çizgisi', 'The author''s line of argument is easy to follow.', 'B2', 23, 4, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_40', 'sweeping statement', 'aşırı genelleyici ifade', 'Saying that all teenagers are lazy is a sweeping statement.', 'B2', 23, 40, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_41', 'bias', 'taraflılık', 'Try to avoid bias when you write about politics.', 'B2', 23, 41, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_42', 'first person', 'birinci şahıs (I, we)', 'Many teachers say you should not write essays in the first person.', 'B2', 23, 42, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_43', 'passive voice', 'edilgen çatı', 'The passive voice is common in scientific writing.', 'B2', 23, 43, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_44', 'informal language', 'gündelik dil', 'Avoid informal language such as ''kids'' or ''a lot of''.', 'B2', 23, 44, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_45', 'slang', 'argo', 'Slang is not appropriate in an academic essay.', 'B2', 23, 45, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_46', 'colloquial', 'konuşma diline ait', 'Words like ''gonna'' are too colloquial for an essay.', 'B2', 23, 46, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_47', 'jargon', 'meslek jargonu', 'The report is full of technical jargon that most readers will not understand.', 'B2', 23, 47, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_48', 'hedging', 'temkinli ifade kullanımı', 'Hedging with words like ''may'' and ''might'' makes claims sound less certain.', 'B2', 23, 48, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_49', 'tentative', 'kesinlik taşımayan', 'The results are only tentative at this stage.', 'B2', 23, 49, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_5', 'logical flow', 'mantıksal akış', 'Your essay needs a logical flow from one idea to the next.', 'B2', 23, 5, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_50', 'overstate', 'olduğundan büyük göstermek', 'Be careful not to overstate the importance of your findings.', 'B2', 23, 50, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_2_7', 'complex', 'karmaşık', 'The issue is complex.', 'B2', 2, 7, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_51', 'caveat', 'çekince', 'One caveat is that the study only included adults.', 'B2', 23, 51, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_52', 'word choice', 'sözcük seçimi', 'Careful word choice makes your writing more precise.', 'B2', 23, 52, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_53', 'impartial', 'tarafsız', 'A news report should be impartial.', 'B2', 23, 53, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_54', 'understatement', 'olduğundan hafif ifade', 'Calling the results ''good'' is an understatement.', 'B2', 23, 54, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_55', 'emotive language', 'duygu yüklü dil', 'Avoid emotive language in a scientific report.', 'B2', 23, 55, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_56', 'redundant', 'gereksiz (fazlalık olan)', 'The word ''very'' is often redundant in academic writing.', 'B2', 23, 56, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_57', 'formatting', 'biçimlendirme', 'Check the formatting of your essay before you submit it.', 'B2', 23, 57, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_58', 'cliché', 'klişe', 'Try to avoid clichés like ''at the end of the day''.', 'B2', 23, 58, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_59', 'readability', 'okunabilirlik', 'Short paragraphs improve readability.', 'B2', 23, 59, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_6', 'academic vocabulary', 'akademik sözcük dağarcığı', 'Reading journal articles helps you build your academic vocabulary.', 'B2', 23, 6, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_60', 'capitalization', 'büyük harf kullanımı', 'Check your spelling and capitalization carefully.', 'B2', 23, 60, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_61', 'quotation marks', 'tırnak işareti', 'Put the exact words of the author in quotation marks.', 'B2', 23, 61, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_62', 'in-text citation', 'metin içi kaynak gösterme', 'Include an in-text citation after every quote.', 'B2', 23, 62, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_63', 'bibliography', 'kaynakça', 'The bibliography lists all the books I used.', 'B2', 23, 63, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_64', 'credible source', 'güvenilir kaynak', 'An anonymous blog is not a credible source.', 'B2', 23, 64, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_65', 'plagiarism', 'intihal', 'Copying someone''s text without giving credit is plagiarism.', 'B2', 23, 65, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_66', 'quotation', 'alıntı', 'He started his speech with a famous quotation.', 'B2', 23, 66, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_67', 'paraphrase', 'başka sözcüklerle ifade etmek', 'Paraphrase the text instead of copying it word for word.', 'B2', 23, 67, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_68', 'primary source', 'birincil kaynak', 'Letters and diaries are useful primary sources.', 'B2', 23, 68, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_69', 'secondary source', 'ikincil kaynak', 'A textbook is usually a secondary source.', 'B2', 23, 69, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_7', 'body paragraph', 'gelişme paragrafı', 'Each body paragraph should focus on one main idea.', 'B2', 23, 7, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_70', 'footnote', 'dipnot', 'The author explains the term in a footnote.', 'B2', 23, 70, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_71', 'concluding paragraph', 'sonuç paragrafı', 'Your concluding paragraph should not introduce new ideas.', 'B2', 23, 71, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_72', 'restate', 'yeniden ifade etmek', 'In the conclusion, restate your thesis in different words.', 'B2', 23, 72, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_73', 'comma splice', 'virgülle yanlış bağlanmış cümle', '''I was tired, I went home.'' is a comma splice.', 'B2', 23, 73, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_74', 'implication', 'olası etki', 'The study has important implications for teachers.', 'B2', 23, 74, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_75', 'hyphen', 'kısa çizgi (-)', 'Use a hyphen in words like "well-known."', 'B2', 23, 75, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_76', 'further research', 'daha ileri araştırma', 'The authors say that further research is needed.', 'B2', 23, 76, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_77', 'recommendation', 'öneri', 'The report ends with several recommendations for schools.', 'B2', 23, 77, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_78', 'double-spaced', 'çift satır aralıklı', 'Essays must be typed and double-spaced.', 'B2', 23, 78, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_79', 'signpost', 'yol gösterici ifade', 'Signposts like ''firstly'' and ''in contrast'' guide the reader.', 'B2', 23, 79, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_8', 'introductory paragraph', 'giriş paragrafı', 'Your introductory paragraph should end with a clear thesis.', 'B2', 23, 8, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_80', 'concluding sentence', 'sonuç cümlesi', 'A good concluding sentence links back to the main idea.', 'B2', 23, 80, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_23_9', 'contraction', 'kaynaştırma kısaltması (don''t, it''s gibi)', 'Avoid contractions like don''t and can''t in formal essays.', 'B2', 23, 9, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_1', 'To whom it may concern', 'İlgili makama', 'The letter began with "To whom it may concern."', 'B2', 24, 1, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_10', 'cc', 'e-postada bilgi kopyasına eklemek', 'Please cc me on any emails to the client.', 'B2', 24, 10, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_11', 'reply all', 'tümünü yanıtlamak', 'Be careful not to hit "reply all" when you only want to answer one person.', 'B2', 24, 11, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_12', 'email thread', 'e-posta yazışma zinciri', 'You can find the details further down in the email thread.', 'B2', 24, 12, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_13', 'contact details', 'iletişim bilgileri', 'My contact details are at the bottom of this email.', 'B2', 24, 13, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_14', 'email signature', 'e-posta imzası', 'Add your phone number to your email signature.', 'B2', 24, 14, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_15', 'formal letter', 'resmî mektup', 'A formal letter should be polite and well organized.', 'B2', 24, 15, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_16', 'salutation', 'mektupta hitap', '"Dear Ms. Lee" is a common salutation in business emails.', 'B2', 24, 16, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_17', 'point of contact', 'irtibat kişisi', 'Sarah will be your main point of contact for this project.', 'B2', 24, 17, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_18', 'inbox', 'gelen kutusu', 'I have more than two hundred unread emails in my inbox.', 'B2', 24, 18, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_19', 'out-of-office reply', 'otomatik "ofis dışındayım" yanıtı', 'I got an out-of-office reply, so she must be on vacation.', 'B2', 24, 19, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_2', 'I am writing to inquire about', '... hakkında bilgi almak için yazıyorum', 'I am writing to inquire about the position advertised on your website.', 'B2', 24, 2, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_20', 'time-sensitive', 'zamanı kısıtlı (acil)', 'This matter is time-sensitive, so please reply today.', 'B2', 24, 20, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_21', 'I would be grateful if', '... yaparsanız minnettar olurum', 'I would be grateful if you could send me the report by Friday.', 'B2', 24, 21, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_22', 'I would appreciate it if', '... yaparsanız sevinirim', 'I would appreciate it if you could call me back today.', 'B2', 24, 22, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_23', 'Would it be possible to', '... mümkün olur mu', 'Would it be possible to move our meeting to Thursday?', 'B2', 24, 23, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_24', 'I was wondering if', 'acaba ... diye merak ediyordum', 'I was wondering if you could help me with the application.', 'B2', 24, 24, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_25', 'at your earliest convenience', 'size uygun olan ilk fırsatta', 'Please reply at your earliest convenience.', 'B2', 24, 25, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_26', 'request a meeting', 'toplantı talep etmek', 'I am writing to request a meeting with your team.', 'B2', 24, 26, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_27', 'reschedule', 'yeniden planlamak', 'Can we reschedule our call for next week?', 'B2', 24, 27, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_28', 'postpone', 'ertelemek', 'We had to postpone the meeting because the manager was sick.', 'B2', 24, 28, '2026-06-11 13:02:44.874361+00');
