INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_30', 'as discussed', 'konuştuğumuz gibi', 'As discussed on the phone, I am sending you the price list.', 'B2', 24, 30, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_31', 'as requested', 'istendiği üzere', 'As requested, I have attached the signed contract.', 'B2', 24, 31, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_32', 'confirmation', 'teyit yazısı', 'We will send you a confirmation by email within 24 hours.', 'B2', 24, 32, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_33', 'approval', 'onay', 'We need the manager''s approval before we can order the supplies.', 'B2', 24, 33, '2026-06-11 13:02:44.874361+00');
