INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_37', 'Please find attached', 'Ekte ... bulabilirsiniz', 'Please find attached my resume and cover letter.', 'B2', 24, 37, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_38', 'enclosed', 'ilişikte gönderilen', 'Enclosed is a copy of the invoice.', 'B2', 24, 38, '2026-06-11 13:02:44.874361+00');
