INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_40', 'gentle reminder', 'nazik bir hatırlatma', 'This is just a gentle reminder that the report is due tomorrow.', 'B2', 24, 40, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_41', 'status update', 'durum bilgisi', 'Could you send me a quick status update on the project?', 'B2', 24, 41, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_42', 'Could you please confirm', 'lütfen teyit eder misiniz', 'Could you please confirm the time of the meeting?', 'B2', 24, 42, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_43', 'keep someone posted', 'birini gelişmelerden haberdar etmek', 'I will keep you posted on any changes.', 'B2', 24, 43, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_44', 'ahead of schedule', 'planlanandan önce', 'The project is two weeks ahead of schedule.', 'B2', 24, 44, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_45', 'on track', 'planlandığı gibi giden', 'We are on track to finish the project by June.', 'B2', 24, 45, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_46', 'Please accept my apologies', 'lütfen özrümü kabul edin', 'Please accept my apologies for the late reply.', 'B2', 24, 46, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_47', 'Kind regards', 'Selamlarımla', 'She ended her email with "Kind regards" and her first name.', 'B2', 24, 47, '2026-06-11 13:02:44.874361+00');
