INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_5', 'in response to', '...e yanıt olarak', 'I am sending this information in response to your request.', 'B2', 24, 5, '2026-06-11 13:02:44.874361+00');
