INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_52', 'touch base', 'kısaca görüşüp durumu konuşmak', 'Let''s touch base next week to discuss the budget.', 'B2', 24, 52, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_53', 'deliverable', 'teslim edilecek iş', 'The first deliverable is a short market report.', 'B2', 24, 53, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_54', 'circle back', 'bir konuya sonra geri dönmek', 'Let''s circle back to this question after lunch.', 'B2', 24, 54, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_55', 'loop in', 'birini yazışmaya dahil etmek', 'I am looping in my colleague, who handles billing.', 'B2', 24, 55, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_56', 'I apologize for the delay', 'Gecikme için özür dilerim', 'I apologize for the delay in getting back to you.', 'B2', 24, 56, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_57', 'Thank you for your patience', 'Sabrınız için teşekkür ederim', 'Thank you for your patience while we fix the problem.', 'B2', 24, 57, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_58', 'rest assured', 'içiniz rahat olsun', 'Rest assured that your data is safe with us.', 'B2', 24, 58, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_59', 'by the end of the day', 'gün sonuna kadar', 'I will send you the final figures by the end of the day.', 'B2', 24, 59, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_6', 'I hope this email finds you well', 'Umarım iyisinizdir', 'I hope this email finds you well and that you had a good weekend.', 'B2', 24, 6, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_60', 'on short notice', 'son dakika haber verilerek', 'Thank you for meeting with me on such short notice.', 'B2', 24, 60, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_61', 'sign-off', 'kapanış ifadesi', 'Choose a polite sign-off, such as "Sincerely."', 'B2', 24, 61, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_62', 'Best regards', 'İyi dileklerimle', 'She always ends her work emails with "Best regards."', 'B2', 24, 62, '2026-06-11 13:02:44.874361+00');
