INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_64', 'Thank you in advance', 'Şimdiden teşekkür ederim', 'Thank you in advance for your help.', 'B2', 24, 64, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_65', 'Thank you for your prompt reply', 'Hızlı yanıtınız için teşekkür ederim', 'Thank you for your prompt reply; it was very helpful.', 'B2', 24, 65, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_2_70', 'goal-oriented', 'hedef odaklı', 'She is goal-oriented.', 'B2', 2, 70, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_66', 'please do not hesitate to contact me', 'benimle iletişime geçmekten çekinmeyin', 'If you have any questions, please do not hesitate to contact me.', 'B2', 24, 66, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_67', 'Should you have any questions', 'Herhangi bir sorunuz olursa', 'Should you have any questions, please call our office.', 'B2', 24, 67, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_68', 'I look forward to hearing from you', 'Sizden haber bekliyorum', 'I look forward to hearing from you soon.', 'B2', 24, 68, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_69', 'Thank you for your understanding', 'Anlayışınız için teşekkür ederim', 'The office will be closed on Friday. Thank you for your understanding.', 'B2', 24, 69, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_7', 'subject line', 'konu satırı', 'Write a clear subject line so the reader knows what the email is about.', 'B2', 24, 7, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_70', 'Thank you for getting back to me', 'Bana dönüş yaptığınız için teşekkür ederim', 'Thank you for getting back to me so quickly.', 'B2', 24, 70, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_71', 'closing line', 'kapanış cümlesi', 'Your closing line should tell the reader what happens next.', 'B2', 24, 71, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_72', 'apologize for any inconvenience', 'yaşanan aksaklık için özür dilemek', 'We apologize for any inconvenience this may cause.', 'B2', 24, 72, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_73', 'acknowledgment of receipt', 'alındı teyidi', 'Acknowledgment of receipt was requested.', 'B2', 24, 73, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_74', 'postscript', 'mektup sonuna eklenen ek not', 'She added a short postscript at the end of the letter.', 'B2', 24, 74, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_75', 'read receipt', 'okundu bilgisi', 'I asked for a read receipt on the email.', 'B2', 24, 75, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_76', 'mailing list', 'e-posta listesi', 'Sign up for our mailing list to get monthly updates.', 'B2', 24, 76, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_77', 'unsubscribe', 'e-posta listesinden çıkmak', 'Click the link at the bottom of the email to unsubscribe.', 'B2', 24, 77, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_78', 'confidential', 'gizli', 'This email is confidential and intended only for the recipient.', 'B2', 24, 78, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_79', 'bcc', 'e-postada gizli kopyaya eklemek', 'I bcc''d my manager so she could see my reply.', 'B2', 24, 79, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_8', 'email etiquette', 'e-posta görgü kuralları', 'Replying within a day is part of good email etiquette.', 'B2', 24, 8, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_80', 'letterhead', 'antetli kâğıt', 'The letter was printed on company letterhead.', 'B2', 24, 80, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_24_9', 'recipient', 'alıcı', 'Check the recipient''s address before you click "Send."', 'B2', 24, 9, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_1', 'logical', 'mantıklı', 'It seems logical to start with the easiest task.', 'B2', 25, 1, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_10', 'presumably', 'tahminen', 'Presumably, the meeting will start on time.', 'B2', 25, 10, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_11', 'make sense of', 'anlamlandırmak', 'It took me a while to make sense of his argument.', 'B2', 25, 11, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_12', 'hold up', 'geçerliliğini korumak (iddia için)', 'His argument does not hold up under close examination.', 'B2', 25, 12, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_13', 'far-fetched', 'inanması zor', 'Her explanation sounds a bit far-fetched.', 'B2', 25, 13, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_14', 'self-evident', 'apaçık', 'The benefits of regular exercise are self-evident.', 'B2', 25, 14, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_15', 'rationale', 'gerekçe', 'What is the rationale behind this decision?', 'B2', 25, 15, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_16', 'chain of reasoning', 'akıl yürütme zinciri', 'If one step is wrong, the whole chain of reasoning breaks down.', 'B2', 25, 16, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_17', 'irrefutable', 'çürütülemez', 'The video provided irrefutable proof of his innocence.', 'B2', 25, 17, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_18', 'logical conclusion', 'mantıklı sonuç', 'The logical conclusion is that we need more staff.', 'B2', 25, 18, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_19', 'appeal to emotion', 'duygulara seslenme safsatası', 'The ad relies on an appeal to emotion rather than facts.', 'B2', 25, 19, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_2', 'airtight', 'açığı olmayan (kusursuz)', 'The lawyer made an airtight case for her client.', 'B2', 25, 2, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_20', 'beyond doubt', 'şüpheye yer bırakmayacak şekilde', 'The tests showed beyond doubt that the drug was safe.', 'B2', 25, 20, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_21', 'reasoning skills', 'akıl yürütme becerileri', 'Chess can help children develop their reasoning skills.', 'B2', 25, 21, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_22', 'false dilemma', 'yanlış ikilem', 'Saying "you are either with us or against us" is a false dilemma.', 'B2', 25, 22, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_23', 'circular reasoning', 'döngüsel akıl yürütme', 'Saying it is true because I said so is circular reasoning.', 'B2', 25, 23, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_24', 'hasty generalization', 'aceleci genelleme', 'Judging a whole city after one short visit is a hasty generalization.', 'B2', 25, 24, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_25', 'appeal to tradition', 'geleneğe başvurma safsatası', '''We have always done it this way'' is an appeal to tradition.', 'B2', 25, 25, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_26', 'red herring', 'dikkati asıl konudan saptıran şey', 'The question about his age was just a red herring.', 'B2', 25, 26, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_27', 'rebuttal', 'karşı görüşü çürüten yanıt', 'The other team prepared a strong rebuttal.', 'B2', 25, 27, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_28', 'valid conclusion', 'geçerli sonuç', 'A valid conclusion must follow from the premises.', 'B2', 25, 28, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_29', 'objection', 'itiraz', 'Does anyone have any objections to the plan?', 'B2', 25, 29, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_3', 'therefore', 'bu nedenle', 'The road was closed; therefore, we had to take another route.', 'B2', 25, 3, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_30', 'counterexample', 'karşı örnek', 'One counterexample is enough to show that the rule is wrong.', 'B2', 25, 30, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_31', 'cherry-pick', 'işine gelen verileri seçmek', 'The report cherry-picks data that supports its conclusion.', 'B2', 25, 31, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_32', 'oversimplify', 'aşırı basitleştirmek', 'The article oversimplifies a very complex issue.', 'B2', 25, 32, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_33', 'appeal to authority', 'otoriteye başvurma safsatası', 'Saying something is true because a celebrity said it is an appeal to authority.', 'B2', 25, 33, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_34', 'debunk', 'yanlış bir inancı boşa çıkarmak', 'The video debunks several common myths about dieting.', 'B2', 25, 34, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_35', 'agree to disagree', 'farklı düşündüğünü kabul edip tartışmayı bırakmak', 'We could not find a solution, so we agreed to disagree.', 'B2', 25, 35, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_36', 'sticking point', 'anlaşmayı tıkayan konu', 'Money was the main sticking point in the negotiations.', 'B2', 25, 36, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_37', 'loophole', 'kanun veya kuraldaki açık', 'The company used a loophole to avoid paying taxes.', 'B2', 25, 37, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_38', 'contradiction in terms', 'kendi içinde çelişkili ifade', 'An "honest thief" is a contradiction in terms.', 'B2', 25, 38, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_39', 'opposing view', 'karşıt görüş', 'A good essay also discusses the opposing view.', 'B2', 25, 39, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_4', 'consequently', 'dolayısıyla', 'He missed the bus and consequently arrived late.', 'B2', 25, 4, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_40', 'faulty logic', 'hatalı mantık', 'The plan is based on faulty logic.', 'B2', 25, 40, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_41', 'chain of events', 'olaylar zinciri', 'One small mistake started a chain of events that closed the factory.', 'B2', 25, 41, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_42', 'causation', 'nedensellik', 'A link between two things does not always mean causation.', 'B2', 25, 42, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_43', 'contributing factor', 'katkıda bulunan etken', 'Stress was a contributing factor in his illness.', 'B2', 25, 43, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_44', 'ripple effect', 'yayılan etki', 'The factory closing had a ripple effect on the whole town.', 'B2', 25, 44, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_45', 'unintended consequence', 'istenmeyen sonuç', 'The new law had several unintended consequences.', 'B2', 25, 45, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_46', 'give rise to', '...e yol açmak', 'The discovery gave rise to new questions.', 'B2', 25, 46, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_47', 'trigger', 'tetiklemek', 'Loud noises can trigger a panic attack.', 'B2', 25, 47, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_48', 'coincidence', 'tesadüf', 'It was pure coincidence that we met at the airport.', 'B2', 25, 48, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_49', 'hard evidence', 'somut kanıt', 'There is no hard evidence that the treatment works.', 'B2', 25, 49, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_5', 'thus', 'böylece', 'Prices went up, thus reducing demand.', 'B2', 25, 5, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_50', 'anecdotal evidence', 'kişisel deneyime dayalı kanıt', 'Anecdotal evidence is not enough to prove a theory.', 'B2', 25, 50, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_51', 'circumstantial evidence', 'dolaylı kanıt', 'He was convicted on circumstantial evidence alone.', 'B2', 25, 51, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_52', 'burden of proof', 'ispat yükü', 'The burden of proof is on the person making the claim.', 'B2', 25, 52, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_53', 'conflicting evidence', 'çelişkili kanıtlar', 'The jury had to weigh a lot of conflicting evidence.', 'B2', 25, 53, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_54', 'testimony', 'tanık ifadesi', 'Her testimony helped the police solve the case.', 'B2', 25, 54, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_55', 'causal link', 'nedensel bağ', 'Scientists found a causal link between smoking and cancer.', 'B2', 25, 55, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_56', 'vicious cycle', 'kısır döngü', 'Poverty and poor health can create a vicious cycle.', 'B2', 25, 56, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_57', 'inconclusive', 'kesin sonuç vermeyen', 'The results of the test were inconclusive.', 'B2', 25, 57, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_58', 'by-product', 'istenmeden ortaya çıkan yan ürün', 'Pollution is a by-product of many industries.', 'B2', 25, 58, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_59', 'loaded question', 'önyargılı varsayım içeren soru', '''Have you stopped cheating?'' is a loaded question.', 'B2', 25, 59, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_6', 'it follows that', 'buradan şu sonuç çıkar', 'If all the tickets are sold, it follows that no one else can enter.', 'B2', 25, 6, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_60', 'a body of evidence', 'kanıt bütünü', 'A growing body of evidence shows that sleep affects memory.', 'B2', 25, 60, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_61', 'moderator', 'tartışma yöneticisi', 'The moderator asked each candidate the same question.', 'B2', 25, 61, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_62', 'false cause', 'yanlış nedensellik safsatası', 'Blaming the rain on your new shoes is a false cause.', 'B2', 25, 62, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_63', 'closing statement', 'kapanış konuşması', 'Each team has two minutes for its closing statement.', 'B2', 25, 63, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_64', 'opening statement', 'açılış konuşması', 'Each team gives a short opening statement before the debate.', 'B2', 25, 64, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_65', 'concession', 'taviz', 'Both sides made concessions to reach an agreement.', 'B2', 25, 65, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_66', 'for and against', 'lehte ve aleyhte', 'We discussed the arguments for and against school uniforms.', 'B2', 25, 66, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_67', 'ad hoc', 'duruma göre uydurulmuş', 'The theory survives only through ad hoc explanations.', 'B2', 25, 67, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_68', 'take the floor', 'söz almak', 'The next speaker took the floor and thanked the audience.', 'B2', 25, 68, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_69', 'have the last word', 'son sözü söylemek', 'She always has to have the last word in an argument.', 'B2', 25, 69, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_25_7', 'inconsistent', 'tutarsız', 'His story is inconsistent with the facts.', 'B2', 25, 7, '2026-06-11 13:02:44.874361+00');
