INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_60', 'territorial waters', 'karasuları', 'The fishing boat was seized in the country''s territorial waters.', 'C1', 16, 60, '2026-06-11 13:02:44.90622+00');
