INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_63', 'admissible', '(delil olarak) kabul edilebilir', 'The judge ruled that the recording was not admissible as evidence.', 'C1', 16, 63, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_64', 'jury duty', 'jüri görevi', 'She was called for jury duty last month.', 'C1', 16, 64, '2026-06-11 13:02:44.90622+00');
