INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_69', 'acquit', 'beraat ettirmek', 'The jury acquitted him of all charges.', 'C1', 16, 69, '2026-06-11 13:02:44.90622+00');
