INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_72', 'hung jury', 'karara varamayan jüri', 'The trial ended with a hung jury, so the case will be heard again.', 'C1', 16, 72, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_73', 'grand jury', 'büyük jüri (iddianame jürisi)', 'A grand jury decided that there was enough evidence for a trial.', 'C1', 16, 73, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_74', 'cross-examination', 'çapraz sorgu', 'The witness changed her story under cross-examination.', 'C1', 16, 74, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_75', 'parole', 'şartlı tahliye', 'He was released on parole after serving ten years.', 'C1', 16, 75, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_76', 'litigation', 'dava süreci', 'The dispute could lead to years of costly litigation.', 'C1', 16, 76, '2026-06-11 13:02:44.90622+00');
