INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_79', 'settle out of court', 'mahkeme dışında uzlaşmak', 'The two companies settled out of court.', 'C1', 16, 79, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_8', 'repeal', 'yürürlükten kaldırmak', 'The new government plans to repeal the controversial law.', 'C1', 16, 8, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_80', 'miscarriage of justice', 'adli hata', 'Sending an innocent man to prison was a terrible miscarriage of justice.', 'C1', 16, 80, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_81', 'advocacy group', 'savunuculuk grubu', 'An advocacy group is helping the families take legal action.', 'C1', 16, 81, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_82', 'human rights defender', 'insan hakları savunucusu', 'The human rights defender was arrested after speaking to journalists.', 'C1', 16, 82, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_83', 'pro bono', 'ücretsiz (hukuki hizmet)', 'The lawyer agreed to take the case pro bono.', 'C1', 16, 83, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_84', 'defamation', 'karalama (itibar zedeleme)', 'The actor sued the newspaper for defamation.', 'C1', 16, 84, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_85', 'restorative justice', 'onarıcı adalet', 'Restorative justice brings victims and offenders together to talk.', 'C1', 16, 85, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_86', 'transitional justice', 'geçiş dönemi adaleti', 'Transitional justice helps societies deal with past abuses after a war.', 'C1', 16, 86, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_87', 'impunity', 'cezasızlık', 'The killings went unpunished, which created a culture of impunity.', 'C1', 16, 87, '2026-06-11 13:02:44.90622+00');
