INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_89', 'truth commission', 'hakikat komisyonu', 'A truth commission investigated crimes committed under the military government.', 'C1', 16, 89, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_9', 'null and void', 'hükümsüz', 'The court declared the contract null and void.', 'C1', 16, 9, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_90', 'arbitration', 'tahkim', 'The contract requires disputes to go to arbitration.', 'C1', 16, 90, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_91', 'grassroots', 'taban (halk düzeyinde)', 'The campaign began as a grassroots movement in small towns.', 'C1', 16, 91, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_92', 'reparations', '(mağdurlara ödenen) tazminat', 'The government agreed to pay reparations to the victims.', 'C1', 16, 92, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_93', 'statute of limitations', 'zamanaşımı', 'The case could not go to court because the statute of limitations had expired.', 'C1', 16, 93, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_94', 'life sentence', 'ömür boyu hapis cezası', 'He is serving a life sentence for murder.', 'C1', 16, 94, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_95', 'civil society', 'sivil toplum', 'Civil society groups monitored the election.', 'C1', 16, 95, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_96', 'wrongful conviction', 'haksız mahkûmiyet', 'DNA evidence later showed that it was a wrongful conviction.', 'C1', 16, 96, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_97', 'arbitrary detention', 'keyfî gözaltı', 'The UN condemned the arbitrary detention of journalists.', 'C1', 16, 97, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_98', 'class action', 'toplu dava', 'Thousands of customers joined a class action against the bank.', 'C1', 16, 98, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_16_99', 'overturn', '(kararı) bozmak', 'The Supreme Court overturned the lower court''s ruling.', 'C1', 16, 99, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_1', 'field experiment', 'saha deneyi', 'A field experiment tests an idea in a real-world setting rather than in a lab.', 'C1', 17, 1, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_10', 'test-retest reliability', 'test-tekrar test güvenirliği', 'Test-retest reliability shows whether a test gives the same results a second time.', 'C1', 17, 10, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_100', 'predatory journal', 'yağmacı dergi', 'A predatory journal will publish almost anything if the authors pay a fee.', 'C1', 17, 100, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_11', 'mixed methods', 'karma yöntem', 'The project used mixed methods, combining surveys with interviews.', 'C1', 17, 11, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_12', 'between-subjects design', 'denekler arası desen', 'In a between-subjects design, each group receives only one treatment.', 'C1', 17, 12, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_13', 'longitudinal study', 'boylamsal çalışma', 'The longitudinal study followed the same children for twenty years.', 'C1', 17, 13, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_14', 'cross-sectional study', 'kesitsel çalışma', 'A cross-sectional study collects data at a single point in time.', 'C1', 17, 14, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_15', 'ecological fallacy', 'ekolojik yanılgı', 'Assuming that every resident is rich because the town is rich is an ecological fallacy.', 'C1', 17, 15, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_16', 'pretest', 'ön test', 'Students took a pretest before the course began.', 'C1', 17, 16, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_17', 'research instrument', 'araştırma aracı (veri toplama aracı)', 'The questionnaire was the main research instrument in the study.', 'C1', 17, 17, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_18', 'within-subjects design', 'denek içi desen', 'In a within-subjects design, every participant tries all conditions.', 'C1', 17, 18, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_19', 'proxy', 'dolaylı gösterge', 'Income is often used as a proxy for social class.', 'C1', 17, 19, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_2', 'control variable', 'kontrol değişkeni', 'Room temperature was kept constant as a control variable.', 'C1', 17, 2, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_20', 'unit of analysis', 'analiz birimi', 'In this study, the unit of analysis is the household.', 'C1', 17, 20, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_21', 'representative sample', 'temsilî örneklem', 'A representative sample should reflect the whole population.', 'C1', 17, 21, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_22', 'target population', 'hedef evren', 'The target population of the survey is adults over 65.', 'C1', 17, 22, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_23', 'nonresponse bias', 'yanıt vermeme yanlılığı', 'Nonresponse bias occurs when the people who do not reply differ from those who do.', 'C1', 17, 23, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_24', 'survey fatigue', 'anket yorgunluğu', 'Survey fatigue leads many people to stop answering halfway through.', 'C1', 17, 24, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_25', 'rating scale', 'derecelendirme ölçeği', 'Pain was measured on a rating scale from 0 to 10.', 'C1', 17, 25, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_26', 'interviewer bias', 'görüşmeci yanlılığı', 'Interviewer bias can occur when the interviewer''s tone influences the answers.', 'C1', 17, 26, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_27', 'social desirability bias', 'sosyal beğenirlik yanlılığı', 'Because of social desirability bias, people tend to underreport how much they drink.', 'C1', 17, 27, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_28', 'primary data', 'birincil veri', 'Primary data was collected through face-to-face interviews.', 'C1', 17, 28, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_29', 'secondary data', 'ikincil veri', 'The study relies on secondary data from government reports.', 'C1', 17, 29, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_3', 'natural experiment', 'doğal deney', 'The sudden change in the law created a natural experiment.', 'C1', 17, 3, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_30', 'missing data', 'eksik veri', 'Missing data can make the results less reliable.', 'C1', 17, 30, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_31', 'survivorship bias', 'hayatta kalma yanlılığı', 'Studying only successful companies leads to survivorship bias.', 'C1', 17, 31, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_32', 'self-report', 'öz bildirim', 'Self-report measures depend on people being honest about themselves.', 'C1', 17, 32, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_33', 'selection bias', 'seçim yanlılığı', 'Choosing only volunteers can introduce selection bias.', 'C1', 17, 33, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_34', 'telephone survey', 'telefon anketi', 'The telephone survey reached 1,500 households.', 'C1', 17, 34, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_35', 'screening question', 'eleme sorusu', 'A screening question made sure that only smokers took part.', 'C1', 17, 35, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_36', 'sampling frame', 'örnekleme çerçevesi', 'The voter list served as the sampling frame.', 'C1', 17, 36, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_37', 'inclusion criteria', 'dahil etme ölçütleri', 'The inclusion criteria required participants to be over 18.', 'C1', 17, 37, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_38', 'dropout rate', '(çalışmayı) bırakma oranı', 'The study had a high dropout rate because many participants quit early.', 'C1', 17, 38, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_39', 'quota sampling', 'kota örneklemesi', 'Quota sampling ensured equal numbers of men and women.', 'C1', 17, 39, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_4', 'quasi-experimental', 'yarı deneysel', 'The study used a quasi-experimental design because random assignment was impossible.', 'C1', 17, 4, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_40', 'stratified sampling', 'tabakalı örnekleme', 'Stratified sampling ensures that every age group is represented.', 'C1', 17, 40, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_41', 'quartile', 'çeyreklik dilim', 'Students in the top quartile received a scholarship.', 'C1', 17, 41, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_42', 'descriptive statistics', 'betimleyici istatistik', 'Descriptive statistics summarize the main features of the data.', 'C1', 17, 42, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_43', 'law of large numbers', 'büyük sayılar yasası', 'The law of large numbers explains why averages become more stable as the sample grows.', 'C1', 17, 43, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_44', 'percentage point', 'yüzde puan', 'Unemployment fell by two percentage points last year.', 'C1', 17, 44, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_45', 'regression to the mean', 'ortalamaya dönüş', 'After an unusually good year, a decline may simply be regression to the mean.', 'C1', 17, 45, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_46', 'blinding', 'körleme', 'Blinding prevents participants from knowing which treatment they receive.', 'C1', 17, 46, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_47', 'time series', 'zaman serisi', 'A time series of monthly prices shows a clear seasonal pattern.', 'C1', 17, 47, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_48', 'multivariate analysis', 'çok değişkenli analiz', 'Multivariate analysis examines several variables at the same time.', 'C1', 17, 48, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_49', 't-test', 't-testi', 'A t-test showed that the two groups differed significantly.', 'C1', 17, 49, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_5', 'random assignment', 'rastgele atama', 'Random assignment means that every participant has the same chance of being in either group.', 'C1', 17, 5, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_3_25', 'pare down', '(gereksizleri atarak) budamak', 'The company pared down its product line to focus on best sellers.', 'C1', 3, 25, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_50', 'standard error', 'standart hata', 'The standard error tells us how precise the estimate is.', 'C1', 17, 50, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_51', 'p-value', 'p değeri', 'A p-value below 0.05 is usually considered significant.', 'C1', 17, 51, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_52', 'normal distribution', 'normal dağılım', 'Adult height roughly follows a normal distribution.', 'C1', 17, 52, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_53', 'variance', 'varyans', 'The variance shows how spread out the scores are.', 'C1', 17, 53, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_54', 'statistical power', 'istatistiksel güç', 'With only 30 participants, the study lacked statistical power.', 'C1', 17, 54, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_55', 'effect size', 'etki büyüklüğü', 'The effect size was small but still meaningful.', 'C1', 17, 55, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_56', 'moving average', 'hareketli ortalama', 'A seven-day moving average smooths out daily changes in the data.', 'C1', 17, 56, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_57', 'cross-tabulation', 'çapraz tablo', 'A cross-tabulation shows how the answers differ by age and gender.', 'C1', 17, 57, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_58', 'robustness check', 'sağlamlık testi', 'Several robustness checks confirmed the main result.', 'C1', 17, 58, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_59', 'chi-square test', 'ki-kare testi', 'A chi-square test showed that the two variables were related.', 'C1', 17, 59, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_6', 'crossover design', 'çapraz geçişli tasarım', 'In a crossover design, each patient receives both treatments in turn.', 'C1', 17, 6, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_60', 'control for', '(bir etkeni) hesaba katarak ayıklamak', 'The researchers controlled for age and income.', 'C1', 17, 60, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_61', 'line of best fit', 'en uygun doğru', 'The line of best fit shows a positive relationship between study time and grades.', 'C1', 17, 61, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_62', 'box plot', 'kutu grafiği', 'The box plot shows the median and the spread of the scores.', 'C1', 17, 62, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_63', 'coding scheme', 'kodlama şeması', 'The researchers developed a coding scheme to sort the interview answers.', 'C1', 17, 63, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_64', 'member checking', 'katılımcı teyidi', 'Through member checking, participants confirmed that the summary of their views was accurate.', 'C1', 17, 64, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_65', 'verbatim', 'kelimesi kelimesine', 'Participants'' answers are quoted verbatim in the report.', 'C1', 17, 65, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_66', 'ceiling effect', 'tavan etkisi', 'The test was too easy, so there was a ceiling effect.', 'C1', 17, 66, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_67', 'null result', 'anlamlı fark çıkmayan sonuç', 'A null result can be just as important as a positive one.', 'C1', 17, 67, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_68', 'causal inference', 'nedensel çıkarım', 'Observational data make causal inference difficult.', 'C1', 17, 68, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_69', 'upward trend', 'artış eğilimi', 'The figures show a clear upward trend in online sales.', 'C1', 17, 69, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_7', 'randomized controlled trial', 'randomize kontrollü çalışma', 'A randomized controlled trial is the most reliable way to test a new drug.', 'C1', 17, 7, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_70', 'thematic analysis', 'tematik analiz', 'Thematic analysis was used to find common ideas in the interviews.', 'C1', 17, 70, '2026-06-11 13:02:44.90622+00');
