INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_72', 'practical significance', 'pratik anlamlılık', 'A result can be statistically significant but have little practical significance.', 'C1', 17, 72, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_73', 'recall bias', 'hatırlama yanlılığı', 'Recall bias is common when people are asked about events from many years ago.', 'C1', 17, 73, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_74', 'error bar', 'hata çubuğu', 'The error bars on the graph show the range of possible values.', 'C1', 17, 74, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_75', 'corresponding author', 'sorumlu yazar', 'Questions about the study should be sent to the corresponding author.', 'C1', 17, 75, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_76', 'large-scale study', 'geniş ölçekli çalışma', 'A large-scale study of 100,000 adults confirmed the link.', 'C1', 17, 76, '2026-06-11 13:02:44.90622+00');
