INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_78', 'data retention', 'veri saklama', 'The data retention policy requires all files to be kept for ten years.', 'C1', 17, 78, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_79', 'preprint', 'ön baskı (hakem onayı öncesi makale)', 'The researchers shared a preprint before the paper was officially published.', 'C1', 17, 79, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_8', 'spurious correlation', 'sahte korelasyon', 'Ice cream sales and drownings show a spurious correlation; both simply rise in summer.', 'C1', 17, 8, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_80', 'publication bias', 'yayın yanlılığı', 'Because of publication bias, studies with positive results are more likely to be published.', 'C1', 17, 80, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_81', 'voluntary participation', 'gönüllü katılım', 'Voluntary participation means that no one is forced to take part in the study.', 'C1', 17, 81, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_82', 'confidentiality', 'gizlilik', 'All answers will be treated with strict confidentiality.', 'C1', 17, 82, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_83', 'duty of care', 'özen yükümlülüğü', 'Researchers have a duty of care toward their participants.', 'C1', 17, 83, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_84', 'consent form', 'onam formu', 'Each participant signed a consent form.', 'C1', 17, 84, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_85', 'anonymize', 'anonimleştirmek', 'All names were removed to anonymize the data.', 'C1', 17, 85, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_86', 'fabrication', '(veri) uydurma', 'The professor lost his job after the fabrication of data was discovered.', 'C1', 17, 86, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_87', 'falsification', '(verileri) tahrif etme', 'The falsification of results led to the paper being withdrawn.', 'C1', 17, 87, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_88', 'vulnerable population', 'kırılgan (korunmaya muhtaç) grup', 'Prisoners are considered a vulnerable population in research.', 'C1', 17, 88, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_89', 'data sharing', 'veri paylaşımı', 'Many journals now require data sharing.', 'C1', 17, 89, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_9', 'reverse causality', 'ters nedensellik', 'Reverse causality is possible: poor health may cause low income, not the other way around.', 'C1', 17, 9, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_90', 'animal testing', 'hayvan deneyleri', 'The company stopped animal testing for its cosmetics.', 'C1', 17, 90, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_3_26', 'step down', 'görevden ayrılmak', 'The director stepped down.', 'C1', 3, 26, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_91', 'retract', '(makaleyi) geri çekmek', 'The journal retracted the paper after serious errors were found.', 'C1', 17, 91, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_92', 'funding body', 'fon sağlayan kurum', 'The funding body had no role in the design of the study.', 'C1', 17, 92, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_93', 'deception', '(deneyde) yanıltma', 'Some psychology experiments use mild deception.', 'C1', 17, 93, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_94', 'metadata', 'üst veri', 'The metadata shows when each file was created.', 'C1', 17, 94, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_95', 'lab notebook', 'laboratuvar defteri', 'Every experiment must be recorded in a lab notebook.', 'C1', 17, 95, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_96', 'right to withdraw', '(çalışmadan) çekilme hakkı', 'Participants have the right to withdraw from the study at any time.', 'C1', 17, 96, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_97', 'audit trail', 'denetim izi', 'An audit trail records every change made to the data.', 'C1', 17, 97, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_98', 'authorship', 'yazarlık', 'Disputes over authorship are common in large research teams.', 'C1', 17, 98, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_17_99', 'biosafety', 'biyogüvenlik', 'The lab follows strict biosafety rules.', 'C1', 17, 99, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_1', 'in the grand scheme of things', 'genel tabloya bakıldığında', 'In the grand scheme of things, a one-day delay is not a big problem.', 'C1', 18, 1, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_10', 'this raises the question of', 'bu şu soruyu gündeme getiriyor', 'This raises the question of accountability.', 'C1', 18, 10, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_100', 'I believe that says it all', 'bence her şeyi anlatıyor', 'I believe that says it all.', 'C1', 18, 100, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_11', 'I would venture to suggest that', 'şunu öne sürmeye cüret ederim', 'I would venture to suggest that the problem is deeper than it looks.', 'C1', 18, 11, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_12', 'it is worth reflecting on', 'üzerinde düşünmeye değer', 'It is worth reflecting on the consequences.', 'C1', 18, 12, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_13', 'I would challenge the idea that', 'şu fikre itiraz ederim', 'I would challenge the idea that speed equals success.', 'C1', 18, 13, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_14', 'there is little evidence to suggest that', 'şunu gösteren pek kanıt yok', 'There is little evidence to suggest that demand will drop.', 'C1', 18, 14, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_15', 'I take a more cautious view', 'daha temkinli bir bakış açısı benimsiyorum', 'I take a more cautious view on this proposal.', 'C1', 18, 15, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_16', 'this strikes me as problematic', 'bu bana sorunlu geliyor', 'This strikes me as problematic in practice.', 'C1', 18, 16, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_17', 'I am not entirely persuaded that', 'şuna tam olarak ikna olmuş değilim', 'I am not entirely persuaded that risks are minimal.', 'C1', 18, 17, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_18', 'it is difficult to overlook the fact that', 'şu gerçeği göz ardı etmek zor', 'It is difficult to overlook the fact that costs increased.', 'C1', 18, 18, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_19', 'I would interpret this as', 'bunu şöyle yorumlardım', 'I would interpret this as a warning sign.', 'C1', 18, 19, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_2', 'what concerns me most is', 'beni en çok endişelendiren şey', 'What concerns me most is the lack of transparency.', 'C1', 18, 2, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_20', 'this deserves closer scrutiny', 'bu daha yakından incelenmeyi hak ediyor', 'This deserves closer scrutiny before approval.', 'C1', 18, 20, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_21', 'I partially agree with the view that', 'şu görüşe kısmen katılıyorum', 'I partially agree with the view that reform is needed.', 'C1', 18, 21, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_22', 'point taken', 'dediğin noktayı kabul ediyorum', 'Point taken. We will check the figures again.', 'C1', 18, 22, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_23', 'that may be true to some extent', 'bu bir ölçüde doğru olabilir', 'That may be true to some extent, but not entirely.', 'C1', 18, 23, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_24', 'I take issue with the claim that', 'şu iddiaya itiraz ediyorum', 'I take issue with the claim that results are neutral.', 'C1', 18, 24, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_25', 'I find it difficult to see how', '...nin nasıl olacağını göremiyorum', 'I find it difficult to see how this plan will save money.', 'C1', 18, 25, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_26', 'there is some merit in saying that', 'şunu söylemekte haklılık payı var', 'There is some merit in saying that experience matters.', 'C1', 18, 26, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_27', 'I couldn''t disagree more', 'kesinlikle katılmıyorum', 'I couldn''t disagree more; the plan will cost far too much.', 'C1', 18, 27, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_28', 'I am torn between two views', 'iki görüş arasında kaldım', 'I am torn between two views on regulation.', 'C1', 18, 28, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_29', 'that argument fails to consider', 'o argüman şunu dikkate almıyor', 'That argument fails to consider long-term effects.', 'C1', 18, 29, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_3', 'I find it hard to accept that', 'şunu kabul etmekte zorlanıyorum', 'I find it hard to accept that this was unavoidable.', 'C1', 18, 3, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_30', 'I acknowledge the point about', 'şu noktayı kabul ediyorum', 'I acknowledge the point about efficiency.', 'C1', 18, 30, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_31', 'I would nuance that by saying', 'bunu şöyle yumuşatırım', 'I would nuance that by saying context matters.', 'C1', 18, 31, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_32', 'I am skeptical about the claim that', 'şu iddiaya şüpheyle yaklaşıyorum', 'I am skeptical about the claim that prices will fall.', 'C1', 18, 32, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_33', 'there is room for disagreement here', 'burada görüş ayrılığına yer var', 'There is room for disagreement here.', 'C1', 18, 33, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_34', 'I do not share the assumption that', 'şu varsayımı paylaşmıyorum', 'I do not share the assumption that growth is endless.', 'C1', 18, 34, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_35', 'that interpretation seems overstated', 'o yorum abartılı görünüyor', 'That interpretation seems overstated to me.', 'C1', 18, 35, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_36', 'I see this somewhat differently', 'bunu biraz farklı görüyorum', 'I see this somewhat differently from you.', 'C1', 18, 36, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_37', 'there is a counterargument to be made', 'karşı bir argüman da var', 'There is a counterargument to be made here.', 'C1', 18, 37, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_38', 'I remain open to the possibility that', 'şu olasılığa açığım', 'I remain open to the possibility that conditions change.', 'C1', 18, 38, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_39', 'that conclusion does not fully follow', 'o sonuç tam olarak çıkmıyor', 'That conclusion does not fully follow from the data.', 'C1', 18, 39, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_4', 'there is a strong case for', 'güçlü bir gerekçe var', 'There is a strong case for changing the policy.', 'C1', 18, 4, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_40', 'I would not go so far as to say that', 'şunu diyecek kadar ileri gitmem', 'I would not go so far as to say that it failed.', 'C1', 18, 40, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_41', 'strictly speaking', 'tam anlamıyla söylemek gerekirse', 'Strictly speaking, a tomato is a fruit, not a vegetable.', 'C1', 18, 41, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_43', 'let me be clear about this', 'bu konuda net olayım', 'Let me be clear about this from the start.', 'C1', 18, 43, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_44', 'for what it''s worth', 'ne kadar işe yarar bilmem ama', 'For what it''s worth, I think you made the right choice.', 'C1', 18, 44, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_45', 'this brings me to my next point', 'bu beni bir sonraki noktaya getiriyor', 'This brings me to my next point.', 'C1', 18, 45, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_46', 'to a large extent', 'büyük ölçüde', 'To a large extent, success depends on trust.', 'C1', 18, 46, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_47', 'to put it simply', 'basitçe söylemek gerekirse', 'To put it simply, we are spending more than we earn.', 'C1', 18, 47, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_48', 'in practical terms', 'pratik açıdan', 'In practical terms, this is costly.', 'C1', 18, 48, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_49', 'for the sake of argument', 'farz edelim ki', 'Let''s assume, for the sake of argument, that the plan works.', 'C1', 18, 49, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_5', 'I can''t help thinking that', 'şöyle düşünmeden edemiyorum', 'I can''t help thinking that we have missed something important.', 'C1', 18, 5, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_50', 'what matters most is', 'en önemli olan şey', 'What matters most is implementation.', 'C1', 18, 50, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_51', 'this is where the difficulty lies', 'zorluk burada yatıyor', 'This is where the difficulty lies.', 'C1', 18, 51, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_52', 'at the heart of the issue is', 'meselenin özünde', 'At the heart of the issue is trust.', 'C1', 18, 52, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_53', 'I would like to stress that', 'şunu vurgulamak isterim', 'I would like to stress that time is limited.', 'C1', 18, 53, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_54', 'in the final analysis', 'son tahlilde', 'In the final analysis, it is the voters who decide.', 'C1', 18, 54, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_55', 'this should be seen in context', 'bu bağlam içinde görülmeli', 'This should be seen in context.', 'C1', 18, 55, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_56', 'one thing leads to another', 'derken iş ilerlemek (bir şey bir şeyi getirmek)', 'We started chatting after the meeting, and one thing led to another.', 'C1', 18, 56, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_57', 'that is not the whole story', 'bu hikâyenin tamamı değil', 'That is not the whole story.', 'C1', 18, 57, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_58', 'as things stand', 'mevcut durumda', 'As things stand, progress is slow.', 'C1', 18, 58, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_59', 'this warrants further discussion', 'bu daha fazla tartışma gerektiriyor', 'This warrants further discussion.', 'C1', 18, 59, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_6', 'one could reasonably argue that', 'şu makul bir şekilde savunulabilir', 'One could reasonably argue that costs will rise.', 'C1', 18, 6, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_60', 'I would frame it as follows', 'bunu şöyle çerçevelerdim', 'I would frame it as follows.', 'C1', 18, 60, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_61', 'I see the logic behind that', 'bunun mantığını görüyorum', 'I see the logic behind that decision.', 'C1', 18, 61, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_62', 'it would be reasonable to assume that', 'şunu varsaymak makul olur', 'It would be reasonable to assume that costs rise.', 'C1', 18, 62, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_63', 'I would urge caution when', 'şu konuda temkinli olmayı öneririm', 'I would urge caution when drawing conclusions.', 'C1', 18, 63, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_64', 'there is no easy answer to this', 'bunun kolay bir cevabı yok', 'There is no easy answer to this.', 'C1', 18, 64, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_65', 'I appreciate your perspective', 'bakış açını takdir ediyorum', 'I appreciate your perspective on the issue.', 'C1', 18, 65, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_66', 'I am mindful of the fact that', 'şu gerçeğin farkındayım', 'I am mindful of the fact that resources are limited.', 'C1', 18, 66, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_67', 'let''s not get ahead of ourselves', 'acele etmeyelim', 'Let''s not get ahead of ourselves; the deal is not signed yet.', 'C1', 18, 67, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_68', 'this may not be ideal, but', 'bu ideal olmayabilir ama', 'This may not be ideal, but it is necessary.', 'C1', 18, 68, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_69', 'I lean toward the view that', 'şu görüşe daha yakınım', 'I lean toward the view that smaller classes help students.', 'C1', 18, 69, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_7', 'it would be misleading to say that', 'şunu söylemek yanıltıcı olur', 'It would be misleading to say that progress is guaranteed.', 'C1', 18, 7, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_70', 'there are trade-offs involved', 'ödünler söz konusu', 'There are trade-offs involved.', 'C1', 18, 70, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_71', 'I would put forward the view that', 'şu görüşü öne sürerim', 'I would put forward the view that regulation helps.', 'C1', 18, 71, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_72', 'I am willing to concede that', 'şunu kabul etmeye hazırım', 'I am willing to concede that mistakes were made.', 'C1', 18, 72, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_73', 'this is easier said than done', 'söylemesi kolay yapması zor', 'This is easier said than done.', 'C1', 18, 73, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_74', 'we need to tread carefully', 'dikkatli ilerlemeliyiz', 'We need to tread carefully here.', 'C1', 18, 74, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_75', 'I am open to reconsidering this', 'bunu yeniden düşünmeye açığım', 'I am open to reconsidering this proposal.', 'C1', 18, 75, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_76', 'that remains to be seen', 'bu henüz belli değil', 'That remains to be seen.', 'C1', 18, 76, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_77', 'with all due respect', 'tüm saygımla', 'With all due respect, I think you are mistaken.', 'C1', 18, 77, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_78', 'this calls for a measured response', 'bu ölçülü bir yanıt gerektiriyor', 'This calls for a measured response.', 'C1', 18, 78, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_79', 'I would refrain from making assumptions', 'varsayım yapmaktan kaçınırım', 'I would refrain from making assumptions.', 'C1', 18, 79, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_8', 'I have my doubts about', '... konusunda şüphelerim var', 'I have my doubts about whether the plan will work.', 'C1', 18, 8, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_80', 'I''m all for it', 'buna tamamen varım (destekliyorum)', 'A shorter workweek? I''m all for it.', 'C1', 18, 80, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_81', 'I rest my case', 'söyleyeceklerim bu kadar (savım kanıtlandı)', 'Sales doubled after the change. I rest my case.', 'C1', 18, 81, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_82', 'the bottom line is that', 'işin özü şu ki', 'The bottom line is that trust matters.', 'C1', 18, 82, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_83', 'I will leave it at that', 'burada bırakacağım', 'I will leave it at that.', 'C1', 18, 83, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_84', 'this is something we need to revisit', 'bunu yeniden ele almalıyız', 'This is something we need to revisit.', 'C1', 18, 84, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_85', 'I stand by my earlier point', 'önceki görüşümün arkasındayım', 'Despite your objections, I stand by my earlier point.', 'C1', 18, 85, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_86', 'this has broader implications', 'bunun daha geniş etkileri var', 'This has broader implications.', 'C1', 18, 86, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_87', 'I would welcome further input', 'ek görüşleri memnuniyetle karşılarım', 'I would welcome further input.', 'C1', 18, 87, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_88', 'that captures my main concern', 'bu ana endişemi özetliyor', 'That captures my main concern.', 'C1', 18, 88, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_89', 'this deserves serious consideration', 'bu ciddi değerlendirme hak ediyor', 'This deserves serious consideration.', 'C1', 18, 89, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_9', 'from my standpoint', 'benim bakış açımdan', 'From my standpoint, clarity is missing.', 'C1', 18, 9, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_90', 'I will reserve judgment for now', 'şimdilik yargımı saklı tutacağım', 'I will reserve judgment for now.', 'C1', 18, 90, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_91', 'I stand corrected', 'yanıldığımı kabul ediyorum', 'I stand corrected; the meeting is on Tuesday, not Monday.', 'C1', 18, 91, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_92', 'I am confident in saying that', 'gönül rahatlığıyla şunu söyleyebilirim', 'I am confident in saying that progress is possible.', 'C1', 18, 92, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_93', 'this reinforces my view that', 'bu şu görüşümü güçlendiriyor', 'This reinforces my view that dialogue matters.', 'C1', 18, 93, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_94', 'I would be curious to hear your thoughts', 'fikirlerini merak ediyorum', 'I would be curious to hear your thoughts.', 'C1', 18, 94, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_95', 'that is a fair assessment', 'bu adil bir değerlendirme', 'That is a fair assessment.', 'C1', 18, 95, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_96', 'I am glad we clarified this', 'bunu netleştirmemize sevindim', 'I am glad we clarified this.', 'C1', 18, 96, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_97', 'this adds an important dimension', 'bu önemli bir boyut ekliyor', 'This adds an important dimension.', 'C1', 18, 97, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_98', 'I''m with you on that', 'bu konuda seninle aynı fikirdeyim', 'I''m with you on that; the meeting is far too long.', 'C1', 18, 98, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_99', 'this opens up new possibilities', 'bu yeni olasılıklar açıyor', 'This opens up new possibilities.', 'C1', 18, 99, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_1', 'to date', 'bugüne kadar', 'To date, few studies have examined this question.', 'C1', 19, 1, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_10', 'the scope of this paper is limited to', 'bu çalışmanın kapsamı şununla sınırlıdır', 'The scope of this paper is limited to Europe.', 'C1', 19, 10, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_100', 'in sum', 'özetle', 'In sum, the evidence supports the new policy.', 'C1', 19, 100, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_11', 'this argument is grounded in', 'bu argüman şuna dayanmaktadır', 'This argument is grounded in empirical evidence.', 'C1', 19, 11, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_12', 'the issue under consideration is', 'ele alınan konu şudur', 'The issue under consideration is accountability.', 'C1', 19, 12, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_13', 'this paper addresses the question of', 'bu makale şu soruyu ele almaktadır', 'This paper addresses the question of equity.', 'C1', 19, 13, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_14', 'the rationale behind this study is', 'bu çalışmanın gerekçesi şudur', 'The rationale behind this study is the lack of reliable local data.', 'C1', 19, 14, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_15', 'this analysis draws upon', 'bu analiz şundan yararlanır', 'This analysis draws upon recent data.', 'C1', 19, 15, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_16', 'the relevance of this topic lies in', 'bu konunun önemi şurada yatmaktadır', 'The relevance of this topic lies in its impact on public health.', 'C1', 19, 16, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_17', 'this discussion is framed around', 'bu tartışma şu çerçevede ele alınır', 'This discussion is framed around ethical concerns.', 'C1', 19, 17, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_18', 'the following sections examine', 'aşağıdaki bölümlerde şu incelenmektedir', 'The following sections examine the causes of the crisis.', 'C1', 19, 18, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_19', 'this paper contributes to the debate on', 'bu makale şu tartışmaya katkı sunar', 'This paper contributes to the debate on reform.', 'C1', 19, 19, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_2', 'this paper sets out to explore', 'bu makale incelemeyi amaçlar', 'This paper sets out to explore recent trends.', 'C1', 19, 2, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_20', 'the focus of this argument will be', 'bu argümanın odağı şu olacaktır', 'The focus of this argument will be efficiency.', 'C1', 19, 20, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_21', 'this can be illustrated by', 'bu şu şekilde örneklendirilebilir', 'This can be illustrated by recent cases.', 'C1', 19, 21, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_22', 'a closer examination reveals that', 'daha yakından incelendiğinde şu görülmektedir', 'A closer examination reveals that outcomes differ.', 'C1', 19, 22, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_23', 'it is important to note that', 'şunu belirtmek önemlidir', 'It is important to note that limitations exist.', 'C1', 19, 23, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_24', 'this suggests that', 'bu şunu düşündürmektedir', 'This suggests that policy changes are needed.', 'C1', 19, 24, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_25', 'one possible explanation for this is', 'bunun olası bir açıklaması şudur', 'One possible explanation for this is the rising cost of energy.', 'C1', 19, 25, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_26', 'this finding is consistent with', 'bu bulgu şununla tutarlıdır', 'This finding is consistent with earlier research.', 'C1', 19, 26, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_27', 'the data indicate that', 'veriler şunu göstermektedir', 'The data indicate that growth slowed.', 'C1', 19, 27, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_28', 'this highlights the importance of', 'bu şunun önemini vurgular', 'This highlights the importance of planning.', 'C1', 19, 28, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_29', 'there is mounting evidence that', 'şuna dair kanıtlar giderek artmaktadır', 'There is mounting evidence that air pollution harms the brain.', 'C1', 19, 29, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_3', 'the following discussion focuses on', 'aşağıdaki tartışma şuna odaklanmaktadır', 'The following discussion focuses on key challenges.', 'C1', 19, 3, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_30', 'this casts doubt on', 'bu, şu konuda şüphe uyandırmaktadır', 'This casts doubt on the official figures.', 'C1', 19, 30, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_31', 'this can be attributed to', 'bu şuna atfedilebilir', 'This can be attributed to external factors.', 'C1', 19, 31, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_32', 'the implications of this are significant', 'bunun sonuçları önemlidir', 'The implications of this are significant.', 'C1', 19, 32, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_33', 'it is no coincidence that', 'şunun tesadüf olmadığı açıktır', 'It is no coincidence that the two crises began in the same year.', 'C1', 19, 33, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_34', 'this is further supported by', 'bu ayrıca şununla desteklenmektedir', 'This is further supported by recent findings.', 'C1', 19, 34, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_35', 'it is widely held that', 'şu yaygın olarak kabul edilmektedir', 'It is widely held that early education shapes later success.', 'C1', 19, 35, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_36', 'this points to a broader trend', 'bu daha geniş bir eğilime işaret eder', 'This points to a broader trend.', 'C1', 19, 36, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_37', 'this example serves to illustrate', 'bu örnek şunu göstermektedir', 'This example serves to illustrate the problem.', 'C1', 19, 37, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_38', 'this analysis demonstrates that', 'bu analiz göstermektedir ki', 'This analysis demonstrates that outcomes vary.', 'C1', 19, 38, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_39', 'this is echoed in', 'bu görüş şurada da dile getirilmektedir', 'This is echoed in several recent government reports.', 'C1', 19, 39, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_4', 'in recent academic discourse', 'son akademik söylemde', 'In recent academic discourse, this topic has gained attention.', 'C1', 19, 4, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_40', 'this section elaborates on', 'bu bölüm şunu ayrıntılı olarak ele almaktadır', 'This section elaborates on key concepts.', 'C1', 19, 40, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_41', 'contrary to expectations', 'beklentilerin aksine', 'Contrary to expectations, sales rose during the crisis.', 'C1', 19, 41, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_42', 'by comparison', 'karşılaştırıldığında', 'By comparison, this approach is simpler.', 'C1', 19, 42, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_43', 'conversely', 'tersine', 'Prices rose in the north; conversely, they fell in the south.', 'C1', 19, 43, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_44', 'this differs markedly from', 'bu belirgin şekilde farklıdır', 'This differs markedly from earlier models.', 'C1', 19, 44, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_45', 'while it is true that', 'doğru olsa da', 'While it is true that costs rose, benefits followed.', 'C1', 19, 45, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_46', 'despite these similarities', 'bu benzerliklere rağmen', 'Despite these similarities, outcomes vary.', 'C1', 19, 46, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_47', 'in stark contrast to', '-in tam aksine', 'In stark contrast to the north, the south saw rapid growth.', 'C1', 19, 47, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_48', 'this stands in opposition to', 'bu, şununla çelişmektedir', 'This stands in opposition to traditional thinking.', 'C1', 19, 48, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_49', 'a key distinction must be made between', 'şu arasında ayrım yapılmalıdır', 'A key distinction must be made between theory and practice.', 'C1', 19, 49, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_5', 'this issue has attracted considerable attention', 'bu konu ciddi ilgi çekmiştir', 'This issue has attracted considerable attention in recent years.', 'C1', 19, 5, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_50', 'this approach differs in that', 'bu yaklaşım şu yönüyle farklıdır', 'This approach differs in that it is flexible.', 'C1', 19, 50, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_51', 'unlike earlier studies', 'önceki çalışmalardan farklı olarak', 'Unlike earlier studies, this paper focuses on long-term effects.', 'C1', 19, 51, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_52', 'this presents a contrast with', 'bu şununla zıtlık gösterir', 'This presents a contrast with prior assumptions.', 'C1', 19, 52, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_53', 'on the contrary', 'aksine', 'The policy did not reduce costs; on the contrary, it raised them.', 'C1', 19, 53, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_54', 'this comparison reveals that', 'bu karşılaştırma şunu ortaya koymaktadır', 'This comparison reveals that efficiency improved.', 'C1', 19, 54, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_55', 'whereas previous research focused on', 'önceki araştırmalar şuna odaklanırken', 'Whereas previous research focused on cost, this focuses on value.', 'C1', 19, 55, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_56', 'this should be distinguished from', 'bu şundan ayırt edilmelidir', 'This should be distinguished from speculation.', 'C1', 19, 56, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_57', 'the difference becomes apparent when', 'fark şu durumda ortaya çıkar', 'The difference becomes apparent when the two groups are compared.', 'C1', 19, 57, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_58', 'diverge from', '-den ayrışmak', 'Her findings diverge sharply from earlier results.', 'C1', 19, 58, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_59', 'a notable contrast emerges between', 'belirgin bir zıtlık ortaya çıkar', 'A notable contrast emerges between the groups.', 'C1', 19, 59, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_6', 'the central aim of this analysis is', 'bu analizin temel amacı şudur', 'The central aim of this analysis is to compare the two policies.', 'C1', 19, 6, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_60', 'this comparison highlights', 'bu karşılaştırma şunu öne çıkarmaktadır', 'This comparison highlights key differences.', 'C1', 19, 60, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_61', 'in light of the findings', 'bulgular ışığında', 'In light of the findings, revision is needed.', 'C1', 19, 61, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_62', 'the results of this analysis suggest that', 'bu analizin sonuçları şunu düşündürmektedir', 'The results of this analysis suggest that change is required.', 'C1', 19, 62, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_63', 'on balance', 'her şey tartıldığında', 'On balance, the benefits outweigh the costs.', 'C1', 19, 63, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_64', 'as might be expected', 'beklenebileceği gibi', 'As might be expected, older participants slept less.', 'C1', 19, 64, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_65', 'this supports the argument that', 'bu şu argümanı destekler', 'This supports the argument that transparency helps.', 'C1', 19, 65, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_66', 'the findings point to the need for', 'bulgular şu ihtiyaca işaret eder', 'The findings point to the need for regulation.', 'C1', 19, 66, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_67', 'particular attention should be paid to', 'şuna özellikle dikkat edilmelidir', 'Particular attention should be paid to the youngest children.', 'C1', 19, 67, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_68', 'the results should be interpreted with caution', 'sonuçlar dikkatle yorumlanmalıdır', 'The results should be interpreted with caution.', 'C1', 19, 68, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_69', 'this raises important considerations regarding', 'bu şu konuda önemli hususlar doğurur', 'This raises important considerations regarding equity.', 'C1', 19, 69, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_7', 'this section provides an overview of', 'bu bölüm genel bir bakış sunar', 'This section provides an overview of the framework.', 'C1', 19, 7, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_19_70', 'the evidence does not conclusively show that', 'kanıt kesin olarak göstermemektedir', 'The evidence does not conclusively show that growth is sustainable.', 'C1', 19, 70, '2026-06-11 13:02:44.91735+00');
