INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_11', 'maintain that', '... olduğunu savunmak', 'He still maintains that he is innocent.', 'C1', 4, 11, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_12', 'proponent', 'savunucu', 'Proponents of the plan say it will create thousands of jobs.', 'C1', 4, 12, '2026-06-11 13:02:44.91735+00');
