INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_16', 'bold claim', 'iddialı sav', 'The author makes the bold claim that cities will disappear.', 'C1', 4, 16, '2026-06-11 13:02:44.91735+00');
