INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_22', 'bolster', 'güçlendirmek', 'New data have bolstered the case for early treatment.', 'C1', 4, 22, '2026-06-11 13:02:44.91735+00');
