INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_26', 'tenable', 'savunulabilir', 'His position is no longer tenable.', 'C1', 4, 26, '2026-06-11 13:02:44.91735+00');
