INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_3', 'watertight', '(sav, gerekçe) hiçbir açığı olmayan', 'Her alibi seemed watertight until a new witness appeared.', 'C1', 4, 3, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_30', 'attest to', '-i kanıtlamak', 'The long lines attest to the restaurant''s popularity.', 'C1', 4, 30, '2026-06-11 13:02:44.91735+00');
