INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_37', 'allege', '(kanıtsız) iddia etmek', 'The report alleges that the company hid the risks.', 'C1', 4, 37, '2026-06-11 13:02:44.91735+00');
