INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_40', 'a matter of opinion', 'kişisel görüş meselesi', 'Whether the movie is good is a matter of opinion.', 'C1', 4, 40, '2026-06-11 13:02:44.91735+00');
