INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_44', 'discredit', 'güvenilirliğini sarsmak', 'The lawyer tried to discredit the witness.', 'C1', 4, 44, '2026-06-11 13:02:44.91735+00');
