INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_5', 'proviso', 'şart (kayıt)', 'They accepted the offer, with the proviso that payment be made in advance.', 'C1', 4, 5, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_50', 'specious', 'aldatıcı biçimde makul görünen', 'His argument is specious: it sounds logical but ignores the facts.', 'C1', 4, 50, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_51', 'scare tactics', 'korkutma taktikleri', 'The campaign used scare tactics to win votes.', 'C1', 4, 51, '2026-06-11 13:02:44.91735+00');
