INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_53', 'point of reference', 'dayanak (referans) noktası', 'The 1990 figures serve as a point of reference for the study.', 'C1', 4, 53, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_54', 'platitude', 'içi boş basmakalıp söz', 'His speech was full of platitudes about hard work.', 'C1', 4, 54, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_55', 'alternative explanation', 'alternatif açıklama', 'Is there an alternative explanation for these results?', 'C1', 4, 55, '2026-06-11 13:02:44.91735+00');
