INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_6', 'line of attack', '(tartışmada) saldırı yolu (strateji)', 'The lawyer changed her line of attack halfway through the trial.', 'C1', 4, 6, '2026-06-11 13:02:44.91735+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_60', 'misrepresent', 'çarpıtarak aktarmak', 'The article misrepresents what the scientists actually said.', 'C1', 4, 60, '2026-06-11 13:02:44.91735+00');
