INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_62', 'thought process', 'düşünme süreci', 'Can you explain your thought process behind this decision?', 'C1', 4, 62, '2026-06-11 13:02:44.91735+00');
