INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_65', 'vice versa', 'tersi de geçerli', 'She doesn''t trust him, and vice versa.', 'C1', 4, 65, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_66', 'inductive generalization', 'tümevarımsal genelleme', 'Inductive generalization moves from specific cases to a general rule.', 'C1', 4, 66, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_67', 'leap of logic', 'mantık sıçraması', 'Moving from one small survey to a global trend is a huge leap of logic.', 'C1', 4, 67, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_68', 'rationalize', '(davranışını) bahanelerle haklı göstermek', 'He rationalized his decision by blaming others.', 'C1', 4, 68, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_69', 'erroneous', 'hatalı, yanlış', 'The report was based on erroneous data.', 'C1', 4, 69, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_7', 'guiding principle', 'yol gösterici ilke', 'Fairness is the guiding principle of the new policy.', 'C1', 4, 7, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_70', 'inferential chain', 'çıkarımsal zincir', 'Each step in the inferential chain must be valid.', 'C1', 4, 70, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_71', 'by extension', 'bunun bir uzantısı olarak', 'The law protects workers and, by extension, their families.', 'C1', 4, 71, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_72', 'illogical', 'mantıksız', 'It is illogical to expect different results from the same method.', 'C1', 4, 72, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_73', 'in turn', 'bu da (sırasıyla)', 'Higher prices reduce demand, which in turn lowers production.', 'C1', 4, 73, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_74', 'in the same vein', 'aynı doğrultuda', 'In the same vein, the second study found no effect.', 'C1', 4, 74, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_75', 'analogy', 'analoji (benzerlik kurarak açıklama)', 'The teacher used an analogy to explain how electricity works.', 'C1', 4, 75, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_76', 'thereby', 'böylece (bu yolla)', 'The company cut costs, thereby increasing its profits.', 'C1', 4, 76, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_77', 'whereby', 'aracılığıyla ...-ebildiği (sistem, düzen)', 'They set up a system whereby users can report problems online.', 'C1', 4, 77, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_78', 'notwithstanding', '-e rağmen', 'Notwithstanding the bad weather, the event was a success.', 'C1', 4, 78, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_79', 'insofar as', '-dığı ölçüde', 'The plan is useful insofar as it reduces costs.', 'C1', 4, 79, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_8', 'overarching thesis', 'kapsayıcı tez', 'The overarching thesis of the book is that cities shape culture.', 'C1', 4, 8, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_80', 'admittedly', 'kabul etmek gerekir ki', 'Admittedly, the plan has some risks.', 'C1', 4, 80, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_81', 'concluding argument', 'sonuç argümanı', 'In her concluding argument, she returned to the main question.', 'C1', 4, 81, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_82', 'tentative conclusion', 'kesinleşmemiş sonuç', 'We can only reach a tentative conclusion from such a small sample.', 'C1', 4, 82, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_83', 'culminate in', 'ile doruğa ulaşmak', 'Years of protest culminated in a new law.', 'C1', 4, 83, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_84', 'ultimately', 'nihayetinde', 'Ultimately, the decision is yours.', 'C1', 4, 84, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_85', 'in essence', 'özünde', 'In essence, the two proposals are the same.', 'C1', 4, 85, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_86', 'unequivocal', 'açık ve kesin', 'The answer was an unequivocal no.', 'C1', 4, 86, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_87', 'theoretical implication', 'kuramsal çıkarım', 'The theoretical implications of the study are discussed in the final chapter.', 'C1', 4, 87, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_88', 'per se', 'kendi başına', 'Money is not bad per se; it depends on how you use it.', 'C1', 4, 88, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_89', 'then again', 'öte yandan', 'The job pays well. Then again, the hours are long.', 'C1', 4, 89, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_9', 'salient', 'göze çarpan (en önemli)', 'The report summarizes the salient points of the debate.', 'C1', 4, 9, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_90', 'key takeaway', 'akılda kalması gereken ana mesaj', 'The key takeaway from the study is that sleep matters.', 'C1', 4, 90, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_91', 'debatable', 'tartışmaya açık', 'Whether the policy worked is debatable.', 'C1', 4, 91, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_92', 'overriding', 'her şeyden önemli', 'Safety is our overriding concern.', 'C1', 4, 92, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_93', 'the upshot', 'işin sonu', 'The upshot of the meeting was a new budget plan.', 'C1', 4, 93, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_94', 'truism', 'herkesin bildiği apaçık gerçek', 'It is a truism that money cannot buy happiness.', 'C1', 4, 94, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_95', 'hedge', '(ifadesini) yumuşatmak', 'Scientists often hedge their claims with words like ''may'' and ''might.''', 'C1', 4, 95, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_96', 'albeit', '-se de (gerçi)', 'The economy is growing, albeit slowly.', 'C1', 4, 96, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_97', 'to that end', 'bu amaçla', 'We want to reduce waste; to that end, we have stopped using plastic bags.', 'C1', 4, 97, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_98', 'in a word', 'tek kelimeyle', 'In a word, the trip was a disaster.', 'C1', 4, 98, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_4_99', 'moot point', 'artık önemi kalmamış konu', 'Whether we could have won is now a moot point.', 'C1', 4, 99, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_1', 'working hypothesis', 'çalışma hipotezi', 'Our working hypothesis was that sleep improves memory.', 'C1', 5, 1, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_10', 'caption', '(şekil, tablo) açıklaması', 'Each figure needs a clear caption.', 'C1', 5, 10, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_100', 'publish or perish', 'ya yayımla ya yok ol', 'In a ''publish or perish'' culture, researchers feel constant pressure.', 'C1', 5, 100, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_11', 'page limit', 'sayfa sınırı', 'The journal has a strict page limit of twenty pages.', 'C1', 5, 11, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_12', 'author guidelines', 'yazar yönergeleri', 'Read the journal''s author guidelines before you submit.', 'C1', 5, 12, '2026-06-11 13:02:44.93019+00');
