INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_14', 'citation style', 'atıf biçimi', 'Check which citation style the journal requires.', 'C1', 5, 14, '2026-06-11 13:02:44.93019+00');
