INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_2', 'research agenda', 'araştırma gündemi', 'Urban poverty is at the top of her research agenda.', 'C1', 5, 2, '2026-06-11 13:02:44.93019+00');
