INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_21', 'review article', 'derleme makale', 'A review article summarizes recent research on a topic.', 'C1', 5, 21, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_22', 'prior research', 'önceki araştırmalar', 'Prior research has shown similar effects in adults.', 'C1', 5, 22, '2026-06-11 13:02:44.93019+00');
