INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_24', 'journal article', 'dergi makalesi', 'The professor asked us to read three journal articles before class.', 'C1', 5, 24, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_25', 'direct quotation', 'doğrudan alıntı', 'Use direct quotations sparingly in your essay.', 'C1', 5, 25, '2026-06-11 13:02:44.93019+00');
