INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_27', 'gap in the literature', 'literatürdeki boşluk', 'This study fills a gap in the literature on rural health.', 'C1', 5, 27, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_28', 'scholar', 'akademisyen (âlim)', 'Scholars disagree about when the text was written.', 'C1', 5, 28, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_29', 'attribute', '(bir sözü, eseri birine) atfetmek', 'The quote is often attributed to Einstein.', 'C1', 5, 29, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_3', 'literature search', 'kaynak araması', 'A careful literature search found only five relevant studies.', 'C1', 5, 3, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_30', 'reputable', 'saygın (itibarlı)', 'Only use data from reputable sources.', 'C1', 5, 30, '2026-06-11 13:02:44.93019+00');
