INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_32', 'systematic review', 'sistematik derleme', 'A systematic review combines the results of many studies on the same question.', 'C1', 5, 32, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_33', 'special issue', '(derginin) özel sayısı', 'The journal published a special issue on climate change.', 'C1', 5, 33, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_34', 'cross-reference', 'çapraz gönderme', 'The handbook includes cross-references to related chapters.', 'C1', 5, 34, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_35', 'theoretical lens', 'kuramsal bakış (mercek)', 'She analyzes the novel through a feminist theoretical lens.', 'C1', 5, 35, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_36', 'academia', 'akademik dünya', 'After ten years in academia, she moved to the private sector.', 'C1', 5, 36, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_37', 'edited volume', 'editörlü derleme kitap', 'The chapter appeared in an edited volume on urban history.', 'C1', 5, 37, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_38', 'scholarly source', 'akademik kaynak', 'Use at least five scholarly sources in your essay.', 'C1', 5, 38, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_39', 'et al.', 've arkadaşları (ve diğerleri)', 'Smith et al. (2020) reported similar results.', 'C1', 5, 39, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_4', 'methods section', 'yöntem bölümü', 'The methods section explains how the data were collected.', 'C1', 5, 4, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_40', 'citation count', 'atıf sayısı', 'Her citation count has doubled in five years.', 'C1', 5, 40, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_41', 'convenience sampling', 'kolay (elverişli) örnekleme', 'Convenience sampling is cheap but may not be representative.', 'C1', 5, 41, '2026-06-11 13:02:44.93019+00');
