INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_45', 'follow-up study', 'izleme çalışması', 'A follow-up study five years later found similar results.', 'C1', 5, 45, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_46', 'control condition', 'kontrol koşulu', 'Participants in the control condition received no training.', 'C1', 5, 46, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_47', 'cohort study', 'kohort çalışması', 'The cohort study tracked 10,000 nurses for thirty years.', 'C1', 5, 47, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_5_48', 'response bias', 'yanıt yanlılığı', 'People''s wish to look good can cause response bias in surveys.', 'C1', 5, 48, '2026-06-11 13:02:44.93019+00');
