INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_10', 'transcendent', 'aşkın', 'Many religions describe God as transcendent.', 'C1', 9, 10, '2026-06-11 13:02:44.93019+00');
