INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_11', 'nothingness', 'hiçlik', 'Existentialist writers were fascinated by the idea of nothingness.', 'C1', 9, 11, '2026-06-11 13:02:44.93019+00');
