INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_19', 'afterlife', 'öbür dünya (ahiret)', 'Many religions teach that there is an afterlife.', 'C1', 9, 19, '2026-06-11 13:02:44.93019+00');
