INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_24', 'fallible', 'yanılabilir', 'Our senses are fallible.', 'C1', 9, 24, '2026-06-11 13:02:44.93019+00');
