INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_27', 'freethinker', 'özgür düşünceli kişi', 'Voltaire was a famous freethinker.', 'C1', 9, 27, '2026-06-11 13:02:44.93019+00');
