INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_32', 'conviction', 'kesin inanç (kanaat)', 'She spoke with deep conviction.', 'C1', 9, 32, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_33', 'blank slate', 'boş levha', 'Locke believed that the mind starts as a blank slate.', 'C1', 9, 33, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_34', 'the Enlightenment', 'Aydınlanma Çağı', 'The Enlightenment celebrated reason and science.', 'C1', 9, 34, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_35', 'line of reasoning', 'akıl yürütme çizgisi', 'I can''t follow your line of reasoning.', 'C1', 9, 35, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_36', 'aphorism', 'özdeyiş (vecize)', '''Knowledge is power'' is a famous aphorism.', 'C1', 9, 36, '2026-06-11 13:02:44.93019+00');
