INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_40', 'dogma', 'dogma (sorgulanmayan inanç)', 'Science should never become a dogma.', 'C1', 9, 40, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_41', 'symbolic logic', 'sembolik mantık', 'Symbolic logic uses letters to stand for statements.', 'C1', 9, 41, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_42', 'entail', 'gerektirmek', 'Being a square entails having four sides.', 'C1', 9, 42, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_43', 'tautology', 'totoloji (her durumda doğru önerme)', '''Either it will rain or it won''t'' is a tautology.', 'C1', 9, 43, '2026-06-11 13:02:44.93019+00');
