INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_47', 'reductio ad absurdum', 'olmayana ergi', 'He used reductio ad absurdum to show that the idea was false.', 'C1', 9, 47, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_48', 'appeal to fear', 'korku yaratma safsatası', 'The campaign relied on an appeal to fear.', 'C1', 9, 48, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_49', 'ad hominem', 'kişiye saldırı safsatası', 'Calling your opponent stupid is an ad hominem attack.', 'C1', 9, 49, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_5', 'innate', 'doğuştan', 'Some philosophers believe that certain ideas are innate.', 'C1', 9, 5, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_50', 'bandwagon fallacy', 'çoğunluğa uyma safsatası', '''Everyone believes it, so it must be true'' is a bandwagon fallacy.', 'C1', 9, 50, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_51', 'false analogy', 'yanlış benzetme safsatası', 'Comparing a country to a household budget is a false analogy.', 'C1', 9, 51, '2026-06-11 13:02:44.93019+00');
