INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_57', 'in principle', 'ilke olarak (kuramsal olarak)', 'In principle, the plan could work.', 'C1', 9, 57, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_58', 'cogent', 'ikna edici (sağlam)', 'She presented a cogent argument.', 'C1', 9, 58, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_59', 'logical connective', 'mantıksal bağlaç', '''And,'' ''or,'' and ''not'' are logical connectives.', 'C1', 9, 59, '2026-06-11 13:02:44.93019+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_9_6', 'first principles', 'ilk ilkeler (temel ilkeler)', 'Aristotle tried to reason from first principles.', 'C1', 9, 6, '2026-06-11 13:02:44.93019+00');
