INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_59', 'conspicuous consumption', 'gösterişçi tüketim', 'Luxury watches are a classic example of conspicuous consumption.', 'C2', 14, 59, '2026-06-11 13:02:44.94216+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_6', 'pecking order', 'gayriresmî hiyerarşi', 'As the new intern, he was at the bottom of the pecking order.', 'C2', 14, 6, '2026-06-11 13:02:44.94216+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_60', 'old money', 'köklü servet sahibi aileler', 'The neighborhood has been home to old money for generations.', 'C2', 14, 60, '2026-06-11 13:02:44.94216+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_61', 'cultural mosaic', 'kültürel mozaik', 'Canada likes to describe itself as a cultural mosaic.', 'C2', 14, 61, '2026-06-11 13:02:44.94216+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_62', 'acculturation', 'kültürleşme', 'Acculturation happens when immigrants adopt parts of a new culture.', 'C2', 14, 62, '2026-06-11 13:02:44.94216+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_63', 'white flight', 'beyazların kent merkezini terk etmesi', 'White flight emptied many American city centers in the 1960s.', 'C2', 14, 63, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_64', 'global citizen', 'dünya vatandaşı', 'Living in five countries made her feel like a global citizen.', 'C2', 14, 64, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_65', 'Westernization', 'Batılılaşma', 'Rapid Westernization changed the country''s fashion and food.', 'C2', 14, 65, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_66', 'McDonaldization', 'McDonaldlaşma', 'Ritzer used the term "McDonaldization" for the spread of fast-food logic across society.', 'C2', 14, 66, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_67', 'glocalization', 'küyerelleşme', 'Glocalization means adapting global products to local tastes.', 'C2', 14, 67, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_68', 'reverse culture shock', 'ters kültür şoku', 'After years abroad, he felt reverse culture shock at home.', 'C2', 14, 68, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_69', 'syncretism', 'bağdaştırmacılık', 'The festival shows religious syncretism, mixing local and Christian beliefs.', 'C2', 14, 69, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_7', 'civic virtue', 'yurttaşlık erdemi', 'Voting and jury service were once seen as acts of civic virtue.', 'C2', 14, 7, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_70', 'cultural lag', 'kültürel gecikme', 'Laws often show a cultural lag behind new technology.', 'C2', 14, 70, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_71', 'lingua franca', 'kabilecilik', 'English has become the lingua franca of science.', 'C2', 14, 71, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_72', 'multiculturalism', 'çok kültürlülük', 'Canada adopted multiculturalism as an official policy.', 'C2', 14, 72, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_73', 'brain drain', 'beyin göçü', 'The country suffers from a brain drain of young doctors.', 'C2', 14, 73, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_74', 'lost in translation', 'çeviride anlamını yitirmek', 'Some jokes get lost in translation.', 'C2', 14, 74, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_75', 'gentrification', 'soylulaştırma', 'Gentrification pushed long-time residents out of the neighborhood.', 'C2', 14, 75, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_76', 'folk wisdom', 'halk bilgeliği', 'Folk wisdom says that a red sky at night means good weather.', 'C2', 14, 76, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_77', 'vernacular', 'halk dili', 'The poet wrote in the vernacular rather than in Latin.', 'C2', 14, 77, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_78', 'counterculture', 'karşı kültür', 'The 1960s counterculture rejected mainstream values.', 'C2', 14, 78, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_79', 'youth culture', 'gençlik kültürü', 'Punk music shaped youth culture in the late 1970s.', 'C2', 14, 79, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_8', 'division of labor', 'iş bölümü', 'The traditional division of labor kept women at home.', 'C2', 14, 8, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_80', 'latchkey kid', 'okuldan sonra evde yalnız kalan çocuk', 'As a latchkey kid, he made his own dinner most nights.', 'C2', 14, 80, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_81', 'zeitgeist', 'çağın ruhu', 'The film captured the zeitgeist of the 1990s.', 'C2', 14, 81, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_82', 'social construct', 'toplumsal kurgu', 'Many scholars see race as a social construct.', 'C2', 14, 82, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_83', 'frame of reference', 'referans çerçevesi', 'Without a shared frame of reference, the joke made no sense.', 'C2', 14, 83, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_84', 'outlook on life', 'hayata bakış', 'Living abroad changed her outlook on life.', 'C2', 14, 84, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_85', 'cultural touchstone', 'kültürel mihenk taşı', 'The TV show became a cultural touchstone for a generation.', 'C2', 14, 85, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_86', 'groupthink', 'grup düşüncesi', 'Groupthink led the committee to ignore the warning signs.', 'C2', 14, 86, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_87', 'herd mentality', 'sürü psikolojisi', 'Herd mentality drove people to panic-buy toilet paper.', 'C2', 14, 87, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_88', 'social solidarity', 'toplumsal dayanışma', 'Shared hardship can strengthen social solidarity.', 'C2', 14, 88, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_89', 'social trust', 'toplumsal güven', 'High social trust makes cooperation easier.', 'C2', 14, 89, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_9', 'folkways', 'gündelik görenekler', 'Folkways are everyday customs, such as how people greet each other.', 'C2', 14, 9, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_90', 'collective unconscious', 'kolektif bilinçdışı', 'Jung believed that myths come from the collective unconscious.', 'C2', 14, 90, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_91', 'common good', 'ortak iyi', 'Citizens should work together for the common good.', 'C2', 14, 91, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_92', 'national identity', 'ulusal kimlik', 'Soccer is an important part of national identity in Brazil.', 'C2', 14, 92, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_93', 'in-group', 'iç grup', 'People tend to favor members of their own in-group.', 'C2', 14, 93, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_94', 'siege mentality', 'kuşatılmışlık psikolojisi', 'Constant criticism gave the team a siege mentality.', 'C2', 14, 94, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_95', 'high culture', 'yüksek kültür', 'The museum aims to make high culture accessible to everyone.', 'C2', 14, 95, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_96', 'social imaginary', 'toplumsal tahayyül', 'Charles Taylor used the term "social imaginary" for how people picture their society.', 'C2', 14, 96, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_97', 'public intellectual', 'kamusal entelektüel', 'As a public intellectual, she often writes for newspapers.', 'C2', 14, 97, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_98', 'global village', 'küresel köy', 'McLuhan predicted that electronic media would turn the world into a global village.', 'C2', 14, 98, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_14_99', 'tastemaker', 'zevk belirleyici', 'Fashion bloggers have become powerful tastemakers.', 'C2', 14, 99, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_1', 'change blindness', 'değişim körlüğü', 'Change blindness explains why viewers miss obvious errors between movie scenes.', 'C2', 15, 1, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_10', 'response inhibition', 'tepki ketlemesi', 'Children with weak response inhibition often act before they think.', 'C2', 15, 10, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_100', 'halo effect', 'hale etkisi', 'Because of the halo effect, attractive people are often judged as more intelligent.', 'C2', 15, 100, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_11', 'mental model', 'zihinsel model', 'Experienced pilots rely on a detailed mental model of the aircraft.', 'C2', 15, 11, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_12', 'semantic memory', 'anlamsal bellek', 'Knowing that Paris is the capital of France is stored in semantic memory.', 'C2', 15, 12, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_13', 'episodic memory', 'epizodik bellek', 'Episodic memory lets you recall what you did on your last birthday.', 'C2', 15, 13, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_14', 'procedural memory', 'işlemsel bellek', 'Riding a bike relies on procedural memory rather than conscious thought.', 'C2', 15, 14, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_15', 'abstract reasoning', 'soyut akıl yürütme', 'The test measures abstract reasoning rather than knowledge.', 'C2', 15, 15, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_16', 'negativity bias', 'olumsuzluk yanlılığı', 'Negativity bias makes one insult outweigh many compliments.', 'C2', 15, 16, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_17', 'mental imagery', 'zihinsel imgeleme', 'Athletes use mental imagery to rehearse a race before it starts.', 'C2', 15, 17, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_18', 'chunking', 'öbekleme', 'Chunking a phone number into groups makes it easier to remember.', 'C2', 15, 18, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_19', 'flashbulb memory', 'flaş bellek (çarpıcı bir olayın canlı anısı)', 'Many people have a flashbulb memory of hearing shocking news.', 'C2', 15, 19, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_2', 'cognitive load', 'bilişsel yük', 'Clear diagrams reduce the cognitive load on students.', 'C2', 15, 2, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_20', 'false memory', 'sahte anı', 'Leading questions can create a false memory of an event.', 'C2', 15, 20, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_21', 'sublimation', 'yüceltme (süblimasyon)', 'Freud saw art as a form of sublimation of hidden desires.', 'C2', 15, 21, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_22', 'alexithymia', 'aleksitimi (duyguları tanıyıp ifade edememe)', 'People with alexithymia struggle to describe their own feelings.', 'C2', 15, 22, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_23', 'emotional reactivity', 'duygusal tepkisellik', 'High emotional reactivity makes small setbacks feel overwhelming.', 'C2', 15, 23, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_24', 'mood-congruent memory', 'duygudurumla uyumlu bellek', 'Mood-congruent memory explains why sad people recall sad events more easily.', 'C2', 15, 24, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_25', 'affective forecasting', 'duygusal öngörü', 'Studies of affective forecasting show that we overestimate how long sadness will last.', 'C2', 15, 25, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_26', 'emotional suppression', 'duygu bastırma', 'Long-term emotional suppression can take a toll on physical health.', 'C2', 15, 26, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_27', 'emotional reasoning', 'duygusal akıl yürütme', 'Emotional reasoning leads people to treat their feelings as facts.', 'C2', 15, 27, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_28', 'anhedonia', 'anhedoni (zevk alamama)', 'Anhedonia, the inability to feel pleasure, is a core symptom of depression.', 'C2', 15, 28, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_29', 'desensitization', 'duyarsızlaşma', 'Repeated exposure to violent images can lead to desensitization.', 'C2', 15, 29, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_3', 'selective attention', 'seçici dikkat', 'Selective attention lets us follow one conversation in a noisy room.', 'C2', 15, 3, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_30', 'emotional valence', 'duygusal değerlik', 'Words with a negative emotional valence are often remembered more easily.', 'C2', 15, 30, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_31', 'priming effect', 'hazırlama etkisi', 'Because of the priming effect, seeing the word "doctor" speeds up recognition of "nurse."', 'C2', 15, 31, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_32', 'loss aversion', 'kayıptan kaçınma', 'Because of loss aversion, losing $100 feels worse than winning $100 feels good.', 'C2', 15, 32, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_33', 'repressed memory', 'bastırılmış anı', 'Some therapists believe a repressed memory can return years later.', 'C2', 15, 33, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_34', 'cognitive reappraisal', 'bilişsel yeniden değerlendirme', 'Cognitive reappraisal means reinterpreting a situation to change how you feel about it.', 'C2', 15, 34, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_35', 'hypervigilance', 'aşırı tetikte olma hali', 'Hypervigilance keeps many trauma survivors constantly on guard.', 'C2', 15, 35, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_36', 'emotional literacy', 'duygusal okuryazarlık', 'Many schools now teach emotional literacy to young children.', 'C2', 15, 36, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_37', 'emotional dysregulation', 'duygu düzenleme güçlüğü', 'Emotional dysregulation can turn minor frustrations into outbursts.', 'C2', 15, 37, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_38', 'habituation', 'alışma (habituasyon)', 'Through habituation, we soon stop noticing the ticking of a clock.', 'C2', 15, 38, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_39', 'psychosomatic', 'psikosomatik', 'Stress can cause psychosomatic symptoms such as headaches.', 'C2', 15, 39, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_4', 'sunk cost fallacy', 'batık maliyet yanılgısı', 'The sunk cost fallacy keeps people watching a bad movie just because they paid for the ticket.', 'C2', 15, 4, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_40', 'psychological reactance', 'yasaklanana yönelme (psikolojik reaktans)', 'Strict rules can trigger psychological reactance, making teenagers want to break them.', 'C2', 15, 40, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_41', 'self-schema', 'benlik şeması', 'If being athletic is part of your self-schema, you notice sports news more.', 'C2', 15, 41, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_42', 'identity diffusion', 'kimlik dağınıklığı', 'Teenagers in a state of identity diffusion have no clear goals or values yet.', 'C2', 15, 42, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_43', 'locus of control', 'denetim odağı', 'People with an internal locus of control believe they shape their own lives.', 'C2', 15, 43, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_44', 'contingent self-esteem', 'koşullu özsaygı', 'People with contingent self-esteem feel worthless after every failure.', 'C2', 15, 44, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_45', 'identity foreclosure', 'kimlik erken kapanması', 'Identity foreclosure occurs when teenagers adopt their parents'' values without question.', 'C2', 15, 45, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_46', 'self-handicapping', 'kendini baltalama', 'Staying out late before an exam can be a form of self-handicapping.', 'C2', 15, 46, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_47', 'personality disorder', 'kişilik bozukluğu', 'A personality disorder affects how people think, feel and relate to others.', 'C2', 15, 47, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_48', 'self-referential processing', 'benliğe referanslı işleme', 'Self-referential processing enhances memory.', 'C2', 15, 48, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_49', 'belief perseverance', 'inanca sıkı sıkıya bağlı kalma', 'Belief perseverance keeps people clinging to ideas even after they are disproved.', 'C2', 15, 49, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_5', 'inattentional blindness', 'dikkatsizlik körlüğü', 'In a famous test of inattentional blindness, viewers failed to notice a person in a gorilla suit.', 'C2', 15, 5, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_1_26', 'oral tradition', 'sözlü gelenek', 'Oral tradition preserved history.', 'C2', 1, 26, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_50', 'self-monitoring', 'öz izleme', 'People high in self-monitoring adjust their behavior to fit each situation.', 'C2', 15, 50, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_51', 'Big Five personality traits', 'Beş Büyük kişilik özelliği', 'The Big Five personality traits include openness, conscientiousness and neuroticism.', 'C2', 15, 51, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_52', 'self-concept differentiation', 'benlik kavramı ayrışması', 'Self-concept differentiation increases flexibility.', 'C2', 15, 52, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_53', 'ego depletion', 'ego tükenmesi', 'According to the theory of ego depletion, willpower weakens after long use.', 'C2', 15, 53, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_54', 'self-serving bias', 'kendine hizmet eden yanlılık', 'Self-serving bias leads us to credit ourselves for success and blame others for failure.', 'C2', 15, 54, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_55', 'ego integrity', 'benlik bütünlüğü', 'Erikson linked ego integrity in old age to accepting one''s life story.', 'C2', 15, 55, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_56', 'spotlight effect', 'spot ışığı etkisi', 'The spotlight effect makes us think everyone notices our mistakes.', 'C2', 15, 56, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_57', 'narrative identity', 'anlatısal kimlik', 'Narrative identity is the life story we build to make sense of who we are.', 'C2', 15, 57, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_58', 'neuroticism', 'nevrotiklik', 'High neuroticism is linked to frequent worry and anxiety.', 'C2', 15, 58, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_59', 'self-construal', 'benlik kurgusu', 'People from collectivist cultures often have an interdependent self-construal.', 'C2', 15, 59, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_6', 'hindsight bias', 'sonradan görme yanlılığı', 'Hindsight bias makes past events seem more predictable than they really were.', 'C2', 15, 6, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_60', 'Dunning-Kruger effect', 'Dunning-Kruger etkisi', 'The Dunning-Kruger effect describes people who greatly overestimate their own skills.', 'C2', 15, 60, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_61', 'psychopathology', 'psikopatoloji', 'The course covers the psychopathology of anxiety and depression.', 'C2', 15, 61, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_62', 'comorbidity', 'eş tanı (komorbidite)', 'Depression shows high comorbidity with anxiety disorders.', 'C2', 15, 62, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_63', 'maladaptive behavior', 'uyum bozucu davranış', 'Avoiding every difficult situation is a maladaptive behavior.', 'C2', 15, 63, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_64', 'diagnostic criteria', 'tanı ölçütleri', 'His symptoms did not meet the diagnostic criteria for depression.', 'C2', 15, 64, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_65', 'chronic stress', 'kronik stres', 'Chronic stress weakens the immune system over time.', 'C2', 15, 65, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_66', 'mood disorder', 'duygudurum bozukluğu', 'Bipolar disorder is a mood disorder marked by extreme highs and lows.', 'C2', 15, 66, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_67', 'confabulation', 'konfabulasyon (farkında olmadan anı uydurma)', 'Patients with memory loss may fill the gaps through confabulation.', 'C2', 15, 67, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_68', 'protective factor', 'koruyucu etken', 'Strong family support is a protective factor against depression.', 'C2', 15, 68, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_69', 'dissociation', 'dissosiyasyon (çözülme)', 'During the accident she experienced dissociation, as if she were watching herself from outside.', 'C2', 15, 69, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_7', 'motivated reasoning', 'güdülenmiş akıl yürütme', 'Motivated reasoning helps people defend the conclusions they already prefer.', 'C2', 15, 7, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_70', 'prognosis', 'prognoz (hastalığın beklenen seyri)', 'Early treatment improves the prognosis for most patients.', 'C2', 15, 70, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_71', 'remission', 'remisyon (belirtilerin geçici olarak kaybolması)', 'After a year of therapy, her depression went into remission.', 'C2', 15, 71, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_72', 'avoidance behavior', 'kaçınma davranışı', 'Avoidance behavior keeps phobias alive.', 'C2', 15, 72, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_73', 'case formulation', 'vaka formülasyonu', 'The therapist''s case formulation linked his anxiety to childhood experiences.', 'C2', 15, 73, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_74', 'treatment-resistant', 'tedaviye dirençli', 'Some patients have treatment-resistant depression that does not respond to medication.', 'C2', 15, 74, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_75', 'panic disorder', 'panik bozukluk', 'Panic disorder involves sudden, repeated attacks of intense fear.', 'C2', 15, 75, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_76', 'relapse', 'nüksetme (hastalığın geri dönmesi)', 'Regular therapy sessions reduce the risk of relapse.', 'C2', 15, 76, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_77', 'psychological distress', 'psikolojik sıkıntı', 'Financial problems are a major source of psychological distress.', 'C2', 15, 77, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_78', 'obsessive-compulsive disorder', 'obsesif-kompulsif bozukluk', 'People with obsessive-compulsive disorder may wash their hands dozens of times a day.', 'C2', 15, 78, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_79', 'vicarious trauma', 'dolaylı travma', 'Journalists who cover wars can suffer from vicarious trauma.', 'C2', 15, 79, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_8', 'anchoring effect', 'çapa etkisi', 'Because of the anchoring effect, the first price we hear shapes our offer.', 'C2', 15, 8, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_80', 'functional impairment', 'işlevsellik kaybı', 'The disorder causes significant functional impairment at work.', 'C2', 15, 80, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_81', 'fundamental attribution error', 'temel yükleme hatası', 'Blaming a late driver''s character instead of the traffic is the fundamental attribution error.', 'C2', 15, 81, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_82', 'theory of mind', 'zihin kuramı', 'Most children develop a theory of mind around the age of four.', 'C2', 15, 82, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_83', 'just-world hypothesis', 'adil dünya inancı', 'The just-world hypothesis leads some people to blame victims for their misfortune.', 'C2', 15, 83, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_84', 'out-group homogeneity', 'dış grup türdeşliği', 'Out-group homogeneity makes us think members of other groups are all alike.', 'C2', 15, 84, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_85', 'pluralistic ignorance', 'çoğulcu cehalet', 'Pluralistic ignorance makes each student think he is the only one who is confused.', 'C2', 15, 85, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_86', 'minority influence', 'azınlık etkisi', 'Minority influence shows that a consistent few can change the majority''s mind.', 'C2', 15, 86, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_87', 'social facilitation', 'sosyal kolaylaştırma', 'Social facilitation explains why cyclists ride faster when racing others.', 'C2', 15, 87, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_88', 'stereotype threat', 'kalıp yargı tehdidi', 'Stereotype threat can lower the test scores of students who fear confirming a stereotype.', 'C2', 15, 88, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_89', 'prosocial behavior', 'toplum yanlısı davranış', 'Helping a stranger is a classic example of prosocial behavior.', 'C2', 15, 89, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_9', 'availability heuristic', 'erişilebilirlik sezgiseli', 'The availability heuristic makes plane crashes seem more common than they are.', 'C2', 15, 9, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_90', 'informational social influence', 'bilgisel sosyal etki', 'Informational social influence leads us to copy others when we are unsure.', 'C2', 15, 90, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_91', 'mere exposure effect', 'salt maruz kalma etkisi', 'The mere exposure effect explains why a song grows on us after repeated listening.', 'C2', 15, 91, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_92', 'foot-in-the-door technique', 'kapıya ayak koyma tekniği', 'Salespeople use the foot-in-the-door technique, starting with a small request.', 'C2', 15, 92, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_93', 'diffusion of responsibility', 'sorumluluğun dağılması', 'In large groups, diffusion of responsibility means no one feels obliged to act.', 'C2', 15, 93, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_94', 'group polarization', 'grup kutuplaşması', 'Online echo chambers intensify group polarization.', 'C2', 15, 94, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_95', 'social loafing', 'sosyal kaytarma', 'Social loafing occurs when people work less hard in a group than alone.', 'C2', 15, 95, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_96', 'collective efficacy', 'kolektif yeterlik', 'Neighborhoods with high collective efficacy tend to have lower crime rates.', 'C2', 15, 96, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_97', 'deindividuation', 'bireysizleşme', 'Deindividuation in crowds can lead people to act in ways they normally would not.', 'C2', 15, 97, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_98', 'bystander effect', 'seyirci etkisi', 'Because of the bystander effect, people are less likely to help when others are present.', 'C2', 15, 98, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_15_99', 'false consensus effect', 'yanlış uzlaşı etkisi', 'The false consensus effect makes us overestimate how many people share our views.', 'C2', 15, 99, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_1', 'extended metaphor', 'genişletilmiş metafor', 'An extended metaphor runs through the whole poem.', 'C2', 16, 1, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_10', 'mixed metaphor', 'karışık metafor', '"We''ll burn that bridge when we come to it" is a humorous mixed metaphor.', 'C2', 16, 10, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_100', 'poetic justice', 'şiirsel adalet (hak edilen son)', 'It was poetic justice when the bully fell into his own trap.', 'C2', 16, 100, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_11', 'transferred epithet', 'aktarılmış sıfat', '"A sleepless night" is a transferred epithet, since nights cannot sleep.', 'C2', 16, 11, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_12', 'anadiplosis', 'ulama yinelemesi (anadiplosis)', '"Fear leads to anger; anger leads to hate" is an example of anadiplosis.', 'C2', 16, 12, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_13', 'dead metaphor', 'ölü metafor', '"The leg of a table" is a dead metaphor that no longer sounds figurative.', 'C2', 16, 13, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_14', 'aposiopesis', 'sözü yarıda kesme (aposiopesis)', '"Get out, or else—" ends in aposiopesis.', 'C2', 16, 14, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_15', 'dysphemism', 'kaba ya da küçültücü söyleyiş (disfemizm)', 'Calling a doctor a "quack" is a dysphemism.', 'C2', 16, 15, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_16', 'synesthesia', 'duyular arası aktarma (sinestezi)', 'Calling a color "loud" is an example of synesthesia.', 'C2', 16, 16, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_17', 'antanaclasis', 'aynı sözcüğü farklı anlamla yineleme', '"If we don''t hang together, we shall surely hang separately" is a famous antanaclasis.', 'C2', 16, 17, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_18', 'parable', 'mesel (ahlaki ders veren öykü)', 'The story of the prodigal son is a parable about forgiveness.', 'C2', 16, 18, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_19', 'epigraph', 'epigraf (kitap başı alıntı)', 'The novel opens with an epigraph from Shakespeare.', 'C2', 16, 19, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_2', 'epic simile', 'destansı benzetme', 'Homer uses an epic simile to compare the charging army to a raging fire.', 'C2', 16, 2, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_20', 'defamiliarization', 'yabancılaştırma', 'Defamiliarization makes everyday objects seem strange and new.', 'C2', 16, 20, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_21', 'onomatopoeia', 'yansıma (ses taklidi)', 'Words like "buzz" and "sizzle" are examples of onomatopoeia.', 'C2', 16, 21, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_22', 'internal rhyme', 'iç uyak', '"Once upon a midnight dreary, while I pondered, weak and weary" contains internal rhyme.', 'C2', 16, 22, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_23', 'assonance', 'asonans (ünlü yinelemesi)', '"Hear the mellow wedding bells" uses assonance on the "e" sound.', 'C2', 16, 23, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_24', 'consonance', 'konsonans (ünsüz yinelemesi)', 'The repeated "k" sound in "stroke of luck" is an example of consonance.', 'C2', 16, 24, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_25', 'euphonic effect', 'ahenkli ses etkisi', 'The euphonic effect of the poem pleases the ear.', 'C2', 16, 25, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_26', 'cacophony', 'kakofoni (kulak tırmalayan ses)', 'The poet uses harsh sounds to create cacophony in the battle scene.', 'C2', 16, 26, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_27', 'meter', 'vezin (ölçü)', 'The poem''s meter slows down in the final stanza.', 'C2', 16, 27, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_28', 'iambic pentameter', 'beşli iambik ölçü', 'Shakespeare wrote most of his plays in iambic pentameter.', 'C2', 16, 28, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_29', 'prosodic variation', 'bürünsel değişkenlik', 'Prosodic variation shapes voice.', 'C2', 16, 29, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_3', 'allegorical representation', 'alegorik temsil', 'Allegorical representation conveys ideology.', 'C2', 16, 3, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_30', 'phonological foregrounding', 'sesbilimsel ön plana çıkarma', 'Phonological foregrounding heightens awareness.', 'C2', 16, 30, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_31', 'refrain', 'tekrarlanan dize (nakarat)', 'The refrain "Nevermore" ends each stanza of the poem.', 'C2', 16, 31, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_32', 'rhyme scheme', 'uyak düzeni', 'Shakespearean sonnets follow the rhyme scheme ABAB CDCD EFEF GG.', 'C2', 16, 32, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_33', 'enjambment', 'dize aşımı (anjambman)', 'Enjambment carries the sentence over into the next line.', 'C2', 16, 33, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_34', 'caesura', 'dize ortası durak (sezür)', 'A caesura in the middle of the line creates a dramatic pause.', 'C2', 16, 34, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_35', 'free verse', 'serbest nazım', 'Walt Whitman wrote much of his poetry in free verse.', 'C2', 16, 35, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_36', 'blank verse', 'uyaksız ölçülü şiir', 'Milton''s "Paradise Lost" is written in blank verse.', 'C2', 16, 36, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_37', 'sound symbolism', 'ses sembolizmi', 'Sound symbolism evokes sensation.', 'C2', 16, 37, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_38', 'couplet', 'beyit', 'Each Shakespearean sonnet ends with a rhyming couplet.', 'C2', 16, 38, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_39', 'sibilance', 'ıslıklı ses yinelemesi', 'The sibilance of "the silken, sad, uncertain rustling" imitates a whisper.', 'C2', 16, 39, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_4', 'hendiadys', 'iki adla tek kavramı anlatma (hendiadis)', '"Nice and warm" is a hendiadys meaning "pleasantly warm."', 'C2', 16, 4, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_40', 'scansion', 'ölçü çözümlemesi', 'Scansion shows where the stressed syllables fall in each line.', 'C2', 16, 40, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_41', 'anaphora', 'söz başı yinelemesi (anafora)', 'Martin Luther King''s repeated "I have a dream" is a famous use of anaphora.', 'C2', 16, 41, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_42', 'epistrophe', 'söz sonu yinelemesi (epifora)', '"Of the people, by the people, for the people" is an example of epistrophe.', 'C2', 16, 42, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_43', 'tricolon', 'üçlü yapı (trikolon)', '"I came, I saw, I conquered" is a classic tricolon.', 'C2', 16, 43, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_44', 'syntactic inversion', 'sözdizimsel tersleme', 'Yoda''s speech is famous for its syntactic inversion.', 'C2', 16, 44, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_45', 'asyndeton', 'bağlaçsızlık (asindeton)', '"We shall pay any price, bear any burden, meet any hardship" uses asyndeton.', 'C2', 16, 45, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_46', 'structural juxtaposition', 'yapısal yan yana getirme', 'Structural juxtaposition highlights contrast.', 'C2', 16, 46, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_47', 'prolepsis', 'ileriye sıçrama (prolepsis)', 'The novel uses prolepsis to reveal the hero''s death in the first chapter.', 'C2', 16, 47, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_48', 'anagnorisis', 'gerçeği tanıma anı (anagnorisis)', 'Oedipus reaches his anagnorisis when he realizes he has killed his father.', 'C2', 16, 48, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_49', 'Chekhov''s gun', 'Çehov''un silahı (öyküdeki her öğenin işlevi olmalı ilkesi)', 'The rifle on the wall in act one is a classic Chekhov''s gun.', 'C2', 16, 49, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_5', 'ekphrasis', 'sanat eserini sözle betimleme (ekfrasis)', 'Keats''s "Ode on a Grecian Urn" is a famous example of ekphrasis.', 'C2', 16, 5, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_50', 'periodic sentence', 'ana fikri sona saklayan cümle', 'A periodic sentence saves its main point until the very end.', 'C2', 16, 50, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_51', 'zeugma', 'zeugma (tek fiile iki farklı anlam yükleme)', '"She broke his car and his heart" is a zeugma.', 'C2', 16, 51, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_52', 'chiasmus', 'çaprazlama (kiazmus)', '"Ask not what your country can do for you, ask what you can do for your country" is a chiasmus.', 'C2', 16, 52, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_53', 'peripeteia', 'talihin ani dönüşü (peripeteia)', 'In Greek tragedy, peripeteia is the sudden reversal of the hero''s fortune.', 'C2', 16, 53, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_54', 'thematic parallelism', 'tematik paralellik', 'Thematic parallelism strengthens cohesion.', 'C2', 16, 54, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_55', 'epistolary novel', 'mektup roman', '"Dracula" is an epistolary novel told through letters and diaries.', 'C2', 16, 55, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_56', 'syntactic foregrounding', 'sözdizimsel ön plana çıkarma', 'Syntactic foregrounding signals importance.', 'C2', 16, 56, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_57', 'bildungsroman', 'gelişim romanı', '"Great Expectations" is a classic bildungsroman.', 'C2', 16, 57, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_58', 'roman à clef', 'gerçek kişileri takma adla anlatan roman', 'The novel is a roman à clef about the author''s famous friends.', 'C2', 16, 58, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_59', 'falling action', 'doruk sonrası bölüm', 'The falling action shows the consequences of the hero''s choice.', 'C2', 16, 59, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_6', 'mock-heroic', 'gülünç-destansı', 'Pope''s mock-heroic poem treats a stolen lock of hair like an epic battle.', 'C2', 16, 6, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_60', 'deus ex machina', 'beklenmedik kurtarıcı (deus ex machina)', 'The sudden arrival of a rich uncle is a lazy deus ex machina.', 'C2', 16, 60, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_61', 'dramatic irony', 'dramatik ironi', 'Dramatic irony intensifies tension.', 'C2', 16, 61, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_62', 'verbal irony', 'sözlü ironi', 'Verbal irony reverses meaning.', 'C2', 16, 62, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_63', 'situational irony', 'durum ironisi', 'Situational irony subverts expectation.', 'C2', 16, 63, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_64', 'tragicomedy', 'trajikomedi', 'The play is a tragicomedy that mixes laughter and grief.', 'C2', 16, 64, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_65', 'the fourth wall', 'dördüncü duvar (sahne ile seyirci arasındaki hayalî sınır)', 'The actor broke the fourth wall by speaking directly to the audience.', 'C2', 16, 65, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_66', 'double entendre', 'çift anlamlı ifade', 'The comedian''s double entendre made the audience laugh.', 'C2', 16, 66, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_67', 'ironic detachment', 'ironik mesafe', 'Ironic detachment signals critique.', 'C2', 16, 67, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_68', 'irony of fate', 'kaderin cilvesi', 'By an irony of fate, the fire station burned down.', 'C2', 16, 68, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_69', 'black comedy', 'kara komedi', '"Dr. Strangelove" is a black comedy about nuclear war.', 'C2', 16, 69, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_7', 'conceptual metaphor', 'kavramsal metafor', '"Time is money" is a conceptual metaphor that shapes how we talk about time.', 'C2', 16, 7, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_70', 'semantic tension', 'anlamsal gerilim', 'Semantic tension sustains interest.', 'C2', 16, 70, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_71', 'ironic juxtaposition', 'ironik yan yana getirme', 'Ironic juxtaposition sharpens critique.', 'C2', 16, 71, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_72', 'antithesis', 'karşıtlık (tezat)', '"It was the best of times, it was the worst of times" is a famous antithesis.', 'C2', 16, 72, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_73', 'subversive irony', 'yıkıcı ironi', 'Subversive irony undermines authority.', 'C2', 16, 73, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_74', 'mise en abyme', 'iç içe yansıtma (mise en abyme)', 'A play within a play, as in Hamlet, creates a mise en abyme.', 'C2', 16, 74, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_75', 'MacGuffin', 'olayları harekete geçiren önemsiz nesne', 'In many spy films, the secret documents are just a MacGuffin.', 'C2', 16, 75, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_76', 'poetic license', 'şiirsel serbestlik', 'The poet took poetic license with the facts of the battle.', 'C2', 16, 76, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_77', 'ironic understatement', 'ironik hafife alma', 'Ironic understatement intensifies critique.', 'C2', 16, 77, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_78', 'dialectical tension', 'diyalektik gerilim', 'Dialectical tension drives argument.', 'C2', 16, 78, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_79', 'ironic resonance', 'ironik yankı', 'Ironic resonance lingers after reading.', 'C2', 16, 79, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_8', 'objective correlative', 'nesnel karşılık', 'Eliot argued that a poet needs an objective correlative to express emotion.', 'C2', 16, 8, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_80', 'malapropism', 'sözcük karıştırma (malapropizm)', '"He is the pineapple of politeness" is a famous malapropism.', 'C2', 16, 80, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_81', 'hypophora', 'soru sorup kendisi yanıtlama (hipofora)', 'In hypophora, the speaker asks a question and immediately answers it.', 'C2', 16, 81, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_82', 'apostrophe', 'seslenme (apostrof)', 'In "O Death, where is thy sting?" the poet uses apostrophe.', 'C2', 16, 82, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_83', 'polysyndeton', 'bağlaç yinelemesi (polisindeton)', '"We have ships and men and money and stores" is an example of polysyndeton.', 'C2', 16, 83, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_84', 'litotes', 'olumsuzlayarak vurgulama (litotes)', 'Saying "not bad at all" about a great meal is litotes.', 'C2', 16, 84, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_85', 'anticlimax', 'düş kırıklığı yaratan son (antiklimaks)', 'After months of build-up, the final episode was an anticlimax.', 'C2', 16, 85, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_86', 'paralipsis', 'söylemeyeceğim diyerek söyleme (paralipsis)', '"I won''t even mention his many failures" is a classic paralipsis.', 'C2', 16, 86, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_87', 'pathos', 'duygulara seslenme (pathos)', 'The ad relies on pathos, showing sad animals to win donations.', 'C2', 16, 87, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_88', 'periphrasis', 'dolaylama', '"The man in the red suit" is a periphrasis for Santa Claus.', 'C2', 16, 88, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_89', 'epanalepsis', 'başta ve sonda aynı sözcüğü yineleme (epanalepsis)', '"The king is dead; long live the king" is an example of epanalepsis.', 'C2', 16, 89, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_9', 'conceit', 'şaşırtıcı ve uzatılmış benzetme', 'John Donne''s famous conceit compares two lovers to the legs of a compass.', 'C2', 16, 9, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_16_90', 'logos', 'mantığa seslenme (logos)', 'The lawyer''s argument relied on logos, presenting facts and statistics.', 'C2', 16, 90, '2026-06-11 13:02:44.950605+00');
