INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_40', 'syllable onset', 'hece başı ünsüzü', 'In "street," the syllable onset is the cluster /str/.', 'C2', 18, 40, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_41', 'acoustic phonetics', 'akustik sesbilgisi', 'Acoustic phonetics studies the physical properties of speech sounds.', 'C2', 18, 41, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_42', 'formant', 'formant', 'The first two formants distinguish most vowels.', 'C2', 18, 42, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_43', 'pitch contour', 'perde eğrisi', 'A rising pitch contour often signals a question.', 'C2', 18, 43, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_44', 'intonational phrase', 'tonlama öbeği', 'A long sentence is often split into several intonational phrases.', 'C2', 18, 44, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_45', 'speech rhythm', 'konuşma ritmi', 'Speech rhythm differs greatly between English and French.', 'C2', 18, 45, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_46', 'speech rate', 'konuşma hızı', 'Nervous speakers often increase their speech rate.', 'C2', 18, 46, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_47', 'sentence stress', 'cümle vurgusu', 'Sentence stress usually falls on the most important word.', 'C2', 18, 47, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_48', 'falling intonation', 'düşen tonlama', 'Statements in English usually end with falling intonation.', 'C2', 18, 48, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_49', 'spectrogram', 'spektrogram', 'A spectrogram shows how the frequencies of speech change over time.', 'C2', 18, 49, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_5', 'oral cavity', 'ağız boşluğu', 'Vowel quality depends on the shape of the oral cavity.', 'C2', 18, 5, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_50', 'speech segmentation', 'konuşma bölütleme', 'Infants must master speech segmentation to find word boundaries.', 'C2', 18, 50, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_51', 'fundamental frequency', 'temel frekans', 'Women''s voices usually have a higher fundamental frequency than men''s.', 'C2', 18, 51, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_52', 'vowel length', 'ünlü uzunluğu', 'In Finnish, vowel length can change the meaning of a word.', 'C2', 18, 52, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_53', 'contrastive stress', 'karşıtlık vurgusu', 'With contrastive stress, "I said BLUE, not green" corrects the listener.', 'C2', 18, 53, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_54', 'tone language', 'ton dili', 'Mandarin is a tone language in which pitch changes word meaning.', 'C2', 18, 54, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_55', 'acoustic cue', 'akustik ipucu', 'Vowel length is an important acoustic cue for consonant voicing.', 'C2', 18, 55, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_56', 'stress-timed language', 'vurgu zamanlı dil', 'English is a stress-timed language.', 'C2', 18, 56, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_57', 'syllable-timed language', 'hece zamanlı dil', 'Spanish is often described as a syllable-timed language.', 'C2', 18, 57, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_58', 'nuclear stress', 'çekirdek vurgusu', 'In "I want TEA," the nuclear stress falls on "tea."', 'C2', 18, 58, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_59', 'rising intonation', 'yükselen tonlama', 'Yes-no questions often end with rising intonation.', 'C2', 18, 59, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_6', 'nasal consonant', 'genizsil ünsüz', 'English has three nasal consonants: m, n and ng.', 'C2', 18, 6, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_60', 'pitch accent', 'perde vurgusu', 'Japanese uses pitch accent to distinguish some words.', 'C2', 18, 60, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_61', 'generative phonology', 'üretici sesbilim', 'Chomsky and Halle founded generative phonology in 1968.', 'C2', 18, 61, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_62', 'constraint ranking', 'kısıt sıralaması', 'Different languages result from different constraint rankings.', 'C2', 18, 62, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_63', 'usage-based phonology', 'kullanım temelli sesbilim', 'Usage-based phonology argues that frequent words change faster.', 'C2', 18, 63, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_64', 'phonology-morphology interface', 'fonoloji-morfoloji arayüzü', 'Phonology-morphology interface explains alternations.', 'C2', 18, 64, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_65', 'phonetics-phonology continuum', 'fonetik-fonoloji sürekliliği', 'Phonetics-phonology continuum challenges boundaries.', 'C2', 18, 65, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_66', 'feature geometry', 'özellik geometrisi', 'Feature geometry arranges phonological features in a tree.', 'C2', 18, 66, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_67', 'lexical phonology', 'sözcüksel sesbilim', 'Lexical phonology links sound rules to word formation.', 'C2', 18, 67, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_68', 'constraint-based analysis', 'kısıt tabanlı analiz', 'Constraint-based analysis predicts outputs.', 'C2', 18, 68, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_69', 'rule ordering', 'kural sıralaması', 'Rule ordering explains why "writer" and "rider" can sound different.', 'C2', 18, 69, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_7', 'vocal folds', 'ses telleri', 'The vocal folds vibrate when we produce voiced sounds.', 'C2', 18, 7, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_70', 'babbling', 'babıldama', 'Infants start babbling at around six months.', 'C2', 18, 70, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_71', 'markedness', 'belirtililik', 'In markedness theory, voiceless stops are less marked than voiced ones.', 'C2', 18, 71, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_72', 'vowel harmony', 'ünlü uyumu', 'Turkish vowel harmony requires suffixes to match the vowels of the root.', 'C2', 18, 72, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_73', 'sound change', 'ses değişimi', 'Sound change can make related words in two languages sound very different.', 'C2', 18, 73, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_74', 'Great Vowel Shift', 'Büyük Ünlü Kayması', 'The Great Vowel Shift explains why English spelling and pronunciation differ.', 'C2', 18, 74, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_75', 'phonological universal', 'sesbilimsel evrensel', 'That all languages have vowels is a phonological universal.', 'C2', 18, 75, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_76', 'consonant cluster', 'ünsüz kümesi', 'Words like "strengths" contain difficult consonant clusters.', 'C2', 18, 76, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_77', 'flapping', 'dil ucu çarpması (t/d yumuşaması)', 'Because of flapping, many Americans pronounce "latter" and "ladder" the same way.', 'C2', 18, 77, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_78', 'faithfulness constraint', 'sadakat kısıtı', 'A faithfulness constraint requires the output to match the input.', 'C2', 18, 78, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_79', 'epenthesis', 'ses türemesi', 'Turkish adds a vowel through epenthesis in loanwords like "kulüp" from "club."', 'C2', 18, 79, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_8', 'phonetic transcription', 'fonetik çevriyazı', 'The dictionary gives a phonetic transcription for every word.', 'C2', 18, 8, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_80', 'metathesis', 'göçüşme (seslerin yer değiştirmesi)', 'Saying "aks" instead of "ask" is an example of metathesis.', 'C2', 18, 80, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_81', 'speech perception', 'konuşma algısı', 'Speech perception remains accurate even in noisy rooms.', 'C2', 18, 81, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_82', 'phonological awareness', 'sesbilimsel farkındalık', 'Rhyming games build children''s phonological awareness.', 'C2', 18, 82, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_83', 'foreign accent', 'yabancı aksanı', 'Adults who learn a language late usually keep a foreign accent.', 'C2', 18, 83, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_84', 'accent bias', 'aksan önyargısı', 'Accent bias can affect hiring decisions.', 'C2', 18, 84, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_85', 'language transfer', 'dil aktarımı', 'Language transfer leads many Turkish speakers to pronounce "think" as "tink."', 'C2', 18, 85, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_86', 'intelligibility', 'anlaşılırlık', 'Clear pronunciation matters more for intelligibility than a perfect accent.', 'C2', 18, 86, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_87', 'categorical perception', 'kategorik algı', 'Categorical perception makes us hear a sound as either /b/ or /p/, with nothing in between.', 'C2', 18, 87, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_88', 'speaker normalization', 'konuşmacıya göre ayarlama', 'Speaker normalization lets us understand both children and adults.', 'C2', 18, 88, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_89', 'McGurk effect', 'McGurk etkisi', 'The McGurk effect shows that seeing lips move changes what we hear.', 'C2', 18, 89, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_9', 'alveolar ridge', 'dişeti çıkıntısı', 'The tongue touches the alveolar ridge to make /t/ and /d/.', 'C2', 18, 9, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_90', 'perceptual adaptation', 'algısal uyum', 'Perceptual adaptation helps us understand an unfamiliar accent after a few minutes.', 'C2', 18, 90, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_91', 'connected speech', 'bağlantılı konuşma', 'In connected speech, "going to" often becomes "gonna."', 'C2', 18, 91, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_92', 'phonological loop', 'sesbilimsel döngü', 'The phonological loop holds words in mind while we repeat them silently.', 'C2', 18, 92, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_93', 'auditory discrimination', 'işitsel ayırt etme', 'Tests of auditory discrimination ask learners to tell "ship" from "sheep."', 'C2', 18, 93, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_94', 'weak form', 'zayıf biçim', 'In fast speech, "can" is usually pronounced in its weak form.', 'C2', 18, 94, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_95', 'schwa', 'şva (vurgusuz belirsiz ünlü)', 'The first vowel in "about" is a schwa.', 'C2', 18, 95, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_96', 'lip-reading', 'dudak okuma', 'Lip-reading helps people with hearing loss follow conversations.', 'C2', 18, 96, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_97', 'interlanguage', 'ara dil', 'A learner''s interlanguage has its own rules, different from both languages.', 'C2', 18, 97, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_98', 'speech accommodation', 'konuşma uyumlaması', 'Through speech accommodation, people adjust their accent to match their partner''s.', 'C2', 18, 98, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_18_99', 'accent reduction', 'aksan azaltma', 'She took an accent reduction course before starting her new job.', 'C2', 18, 99, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_1', 'ambiguity', 'belirsizlik', 'Ambiguity weakens interpretation.', 'C2', 19, 1, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_10', 'ill-defined', 'iyi tanımlanmamış', 'The project failed because its goals were ill-defined.', 'C2', 19, 10, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_100', 'unresolved', 'çözümsüz kalmış', 'The question of who wrote the letter remains unresolved.', 'C2', 19, 100, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_11', 'amorphous', 'biçimsiz, şekilsiz (belirgin yapısı olmayan)', 'The movement remained an amorphous group with no clear leader.', 'C2', 19, 11, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_12', 'anybody''s guess', 'kimsenin kestiremeyeceği şey', 'What the court will decide is anybody''s guess.', 'C2', 19, 12, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_13', 'hazy', 'bulanık (zihinde net olmayan)', 'My memory of that night is hazy.', 'C2', 19, 13, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_14', 'semantic indeterminacy', 'anlamsal belirsizlik', 'Semantic indeterminacy challenges definition.', 'C2', 19, 14, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_15', 'murky', 'karanlık ve anlaşılmaz', 'The origins of the custom are murky.', 'C2', 19, 15, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_16', 'ambiguous phrasing', 'belirsiz ifade biçimi', 'Ambiguous phrasing misleads readers.', 'C2', 19, 16, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_17', 'cryptic', 'şifreli, esrarengiz', 'She left a cryptic note that no one could understand.', 'C2', 19, 17, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_18', 'imprecise', 'kesinlikten uzak', 'The witness descriptions were too imprecise to identify the thief.', 'C2', 19, 18, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_19', 'conceptual ambiguity', 'kavramsal belirsizlik', 'Conceptual ambiguity obscures boundaries.', 'C2', 19, 19, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_2', 'tolerance of ambiguity', 'belirsizliğe tahammül', 'Good negotiators have a high tolerance of ambiguity.', 'C2', 19, 2, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_20', 'a shot in the dark', 'körü körüne tahmin', 'My answer was just a shot in the dark.', 'C2', 19, 20, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_21', 'polysemy', 'çok anlamlılık', 'The polysemy of "run" makes it hard for learners.', 'C2', 19, 21, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_22', 'homonym', 'eş sesli sözcük', '"Bat" is a homonym: it can mean an animal or a piece of sports equipment.', 'C2', 19, 22, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_23', 'syntactic ambiguity', 'sözdizimsel belirsizlik', '"Visiting relatives can be boring" is a classic case of syntactic ambiguity.', 'C2', 19, 23, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_24', 'garden-path sentence', 'yanıltıcı yapılı cümle', '"The old man the boat" is a famous garden-path sentence.', 'C2', 19, 24, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_25', 'dangling modifier', 'sarkık niteleyici', '"Walking home, the rain started" contains a dangling modifier.', 'C2', 19, 25, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_26', 'referential ambiguity', 'gönderim belirsizliği', 'Referential ambiguity hides the subject.', 'C2', 19, 26, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_27', 'misplaced modifier', 'yanlış yerleştirilmiş niteleyici', '"She almost drove her kids to school every day" has a misplaced modifier.', 'C2', 19, 27, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_28', 'attachment ambiguity', 'bağlanma belirsizliği', '"I saw the man with the telescope" shows attachment ambiguity.', 'C2', 19, 28, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_29', 'mondegreen', 'yanlış duyulan şarkı sözü', 'Hearing "kiss this guy" instead of "kiss the sky" is a famous mondegreen.', 'C2', 19, 29, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_3', 'indeterminate', 'belirsiz (kesinleştirilemeyen)', 'The age of the manuscript remains indeterminate.', 'C2', 19, 3, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_30', 'coordination ambiguity', 'bağlaçlı yapı belirsizliği', '"Old men and women" shows coordination ambiguity.', 'C2', 19, 30, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_31', 'scope ambiguity', 'kapsam belirsizliği', '"All the students didn''t pass" contains a scope ambiguity.', 'C2', 19, 31, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_32', 'eggcorn', 'yanlış ama mantıklı görünen sözcük (eggcorn)', 'Writing "for all intensive purposes" is a common eggcorn.', 'C2', 19, 32, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_33', 'mishear', 'yanlış duymak', 'I misheard "fourteen" as "forty."', 'C2', 19, 33, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_34', 'misconstrue', 'yanlış yorumlamak', 'Her silence was misconstrued as agreement.', 'C2', 19, 34, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_35', 'take something the wrong way', 'yanlış anlayıp alınmak', 'Please don''t take this the wrong way, but your report is too long.', 'C2', 19, 35, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_36', 'untranslatable', 'çevrilemez', 'The Turkish word "hüzün" is often called untranslatable.', 'C2', 19, 36, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_37', 'get one''s wires crossed', 'birbirini yanlış anlamak', 'We got our wires crossed and went to different restaurants.', 'C2', 19, 37, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_38', 'lose the thread', 'konunun ipini kaçırmak', 'I lost the thread of his argument halfway through.', 'C2', 19, 38, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_39', 'antecedent', 'öncül (zamirin gönderdiği öğe)', 'In "John told Bill he was late," the antecedent of "he" is unclear.', 'C2', 19, 39, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_4', 'nebulous', 'muğlak (şekillenmemiş)', 'The company''s plans for the future remain nebulous.', 'C2', 19, 4, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_40', 'serial comma', 'dizi virgülü (Oxford virgülü)', 'Without the serial comma, "my parents, Ayn Rand and God" sounds very strange.', 'C2', 19, 40, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_41', 'pragmatic ambiguity', 'pragmatik belirsizlik', 'Pragmatic ambiguity hides intention.', 'C2', 19, 41, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_42', 'word salad', 'anlamsız söz yığını', 'His answer was a confusing word salad that explained nothing.', 'C2', 19, 42, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_43', 'underspecified meaning', 'yetersiz belirlenmiş anlam', 'Underspecified meaning invites assumptions.', 'C2', 19, 43, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_44', 'contextual ambiguity', 'bağlamsal belirsizlik', 'Contextual ambiguity shifts interpretation.', 'C2', 19, 44, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_45', 'mixed message', 'çelişkili mesaj', 'Parents who say "no" but then laugh are sending a mixed message.', 'C2', 19, 45, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_46', 'trick question', 'tuzak soru', '"Have you stopped cheating on tests?" is a trick question.', 'C2', 19, 46, '2026-06-11 13:02:44.950605+00');
