INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_48', 'unstated assumption', 'belirtilmemiş varsayım', 'The argument rests on an unstated assumption.', 'C2', 19, 48, '2026-06-11 13:02:44.950605+00');
