INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_55', 'indefinitely', 'süresiz olarak', 'The talks have been postponed indefinitely.', 'C2', 19, 55, '2026-06-11 13:02:44.950605+00');
