INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_6', 'lexical ambiguity', 'sözcüksel belirsizlik', 'Lexical ambiguity allows multiple readings.', 'C2', 19, 6, '2026-06-11 13:02:44.950605+00');
