INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_65', 'terminological ambiguity', 'terminolojik belirsizlik', 'Terminological ambiguity confuses discourse.', 'C2', 19, 65, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_20_90', 'dig one''s heels in', 'ayak diremek', 'The board dug its heels in and refused to change the plan.', 'C2', 20, 90, '2026-06-11 13:02:44.958908+00');
