INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_75', 'indistinct', 'seçilemeyen (net duyulmayan)', 'We heard indistinct voices behind the door.', 'C2', 19, 75, '2026-06-11 13:02:44.950605+00');
