INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_79', 'semantic bleaching', 'anlam aşınması', 'Semantic bleaching has turned "awesome" into a word for anything good.', 'C2', 19, 79, '2026-06-11 13:02:44.950605+00');
