INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_80', 'in limbo', 'arafta (belirsizlik içinde)', 'Thousands of refugees are left in limbo while their cases are reviewed.', 'C2', 19, 80, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_81', 'strategic ambiguity', 'stratejik belirsizlik', 'Strategic ambiguity preserves flexibility.', 'C2', 19, 81, '2026-06-11 13:02:44.950605+00');
