INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_89', 'talk in riddles', 'bilmece gibi konuşmak', 'Stop talking in riddles and tell me what happened.', 'C2', 19, 89, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_9', 'elusive', 'tanımlaması zor', 'The exact meaning of the poem remains elusive.', 'C2', 19, 9, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_90', 'policy ambiguity', 'politika belirsizliği', 'Policy ambiguity enables negotiation.', 'C2', 19, 90, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_91', 'evasive', 'kaçamak', 'He gave evasive answers to every question.', 'C2', 19, 91, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_92', 'constructive ambiguity', 'yapıcı belirsizlik', 'Constructive ambiguity facilitates agreement.', 'C2', 19, 92, '2026-06-11 13:02:44.950605+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C2_19_93', 'coded language', 'üstü kapalı (şifreli) dil', 'The speech used coded language that only supporters understood.', 'C2', 19, 93, '2026-06-11 13:02:44.950605+00');
